css:
.apl-week {
  /* theme: override these four to re-skin */
  --apl-week-bg: oklch(0.985 0.005 85);
  --apl-week-ink: oklch(0.24 0.02 55);
  --apl-week-accent: oklch(0.63 0.19 32);
  --apl-week-surface: oklch(0.998 0.002 85);
  --apl-week-hh: 48px;
  --apl-week-line: color-mix(in oklch, var(--apl-week-ink) 10%, transparent);
  --apl-week-line2: color-mix(in oklch, var(--apl-week-ink) 18%, transparent);
  --apl-week-mute: color-mix(in oklch, var(--apl-week-ink) 56%, var(--apl-week-bg));
  --apl-week-faint: color-mix(in oklch, var(--apl-week-ink) 34%, var(--apl-week-bg));
  --apl-week-wash: color-mix(in oklch, var(--apl-week-ink) 3.5%, var(--apl-week-bg));
  --apl-week-tint: color-mix(in oklab, var(--apl-week-accent) 10%, var(--apl-week-bg));
  --apl-week-ease: cubic-bezier(.2, .8, .2, 1);
  --apl-week-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--apl-week-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-week-bg); color: var(--apl-week-ink); color-scheme: light;
  accent-color: var(--apl-week-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 10px; box-shadow: 0 0 0 1px var(--apl-week-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-week-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & p { margin: 0; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; text-align: center;
    border: 1px solid var(--apl-week-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-week-mute);
    background: var(--apl-week-surface);
  }
}

.apl-week .apl-week-app {
  height: 100%; display: grid; grid-template-columns: 236px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "side head" "side main";
}

/* ── sidebar ───────────────────────────────────────── */
.apl-week .apl-week-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none;
  display: flex; flex-direction: column; gap: 18px; padding: 16px 14px 14px;
  background: var(--apl-week-wash); border-right: 1px solid var(--apl-week-line);
}
.apl-week .apl-week-brand {
  display: grid; grid-template-columns: auto 1fr; column-gap: 9px; align-items: center; padding: 0 4px;
  & svg { grid-row: span 2; width: 26px; height: 26px; color: var(--apl-week-accent); stroke-width: 1.6; }
  & svg .f { fill: currentColor; stroke: none; }
  & span { font-weight: 750; letter-spacing: -.01em; font-size: 14px; }
  & small { font-size: 11px; color: var(--apl-week-mute); }
}
.apl-week .apl-week-new {
  display: flex; align-items: center; gap: 8px; padding: 10px 12px; border: 0; border-radius: 10px;
  background: var(--apl-week-ink); color: var(--apl-week-bg); font-weight: 650;
  box-shadow: 0 1px 0 color-mix(in oklch, var(--apl-week-ink) 30%, transparent), 0 6px 16px -8px color-mix(in oklch, var(--apl-week-ink) 60%, transparent);
  transition: scale .3s var(--apl-week-spring), background .2s;
  & kbd { margin-left: auto; background: transparent; color: inherit; border-color: color-mix(in oklch, var(--apl-week-bg) 35%, transparent); }
  &:hover { background: color-mix(in oklch, var(--apl-week-ink) 88%, var(--apl-week-accent)); }
  &:active { scale: .97; }
}
.apl-week .apl-week-mini {
  & header { display: flex; align-items: center; gap: 2px; padding: 0 2px 6px 6px; }
  & header b { flex: 1; font-size: 12.5px; font-weight: 700; }
  & header button { border: 0; background: none; padding: 4px; border-radius: 6px; color: var(--apl-week-mute); display: grid; }
  & header button:hover { background: var(--apl-week-line); color: var(--apl-week-ink); }
}
.apl-week .apl-week-mgrid {
  display: grid; grid-template-columns: repeat(7, 1fr); row-gap: 2px;
  & span { font-size: 9.5px; font-weight: 700; color: var(--apl-week-faint); text-align: center; padding-bottom: 3px; letter-spacing: .04em; }
  & button {
    position: relative; border: 0; background: none; aspect-ratio: 1; display: grid; place-items: center;
    font-size: 11.5px; font-variant-numeric: tabular-nums; border-radius: 7px; color: var(--apl-week-ink);
    transition: background .15s;
    &:hover { background: var(--apl-week-line); }
    &.is-out { color: var(--apl-week-faint); }
    &.is-dot::after { content: ""; position: absolute; bottom: 3px; width: 3px; height: 3px; border-radius: 50%; background: var(--apl-week-faint); }
    &.is-band { background: var(--apl-week-tint); border-radius: 0; }
    &.is-band-s { border-radius: 7px 0 0 7px; }
    &.is-band-e { border-radius: 0 7px 7px 0; }
    &.is-today { color: var(--apl-week-accent); font-weight: 800; }
    &.is-today::after { background: var(--apl-week-accent); }
    &[aria-current="date"] { box-shadow: inset 0 0 0 1.5px var(--apl-week-accent); border-radius: 7px; }
  }
}
.apl-week .apl-week-cals {
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--apl-week-mute); padding: 0 6px 6px; display: flex; }
  & h3 span { margin-left: auto; font-weight: 600; letter-spacing: .02em; text-transform: none; color: var(--apl-week-faint); }
  & ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; }
  & label {
    display: grid; grid-template-columns: auto 1fr auto; gap: 8px; align-items: center; padding: 5px 6px; border-radius: 7px; cursor: pointer;
    transition: background .15s, opacity .2s;
    &:hover { background: var(--apl-week-line); }
    &:has(input:not(:checked)) { opacity: .55; }
    &:has(input:not(:checked)) b { text-decoration: line-through; text-decoration-color: var(--apl-week-faint); }
  }
  & input { margin: 0; width: 15px; height: 15px; accent-color: var(--c); }
  & b { font-weight: 550; font-size: 12.5px; }
  & output { font: 500 11px ui-monospace, Menlo, monospace; color: var(--apl-week-mute); font-variant-numeric: tabular-nums; }
}
.apl-week .apl-week-sum {
  margin-top: auto; padding: 12px; border-radius: 12px; background: var(--apl-week-surface); box-shadow: 0 0 0 1px var(--apl-week-line);
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--apl-week-mute); }
  & strong { display: block; margin: 4px 0 2px; font-size: 24px; font-weight: 750; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & p { font-size: 11.5px; color: var(--apl-week-mute); text-wrap: pretty; }
  & .apl-week-bar { display: flex; height: 6px; gap: 2px; margin-top: 10px; border-radius: 3px; overflow: hidden; background: var(--apl-week-line); }
  & .apl-week-bar i { height: 100%; background: var(--c); flex: 0 0 calc(var(--p) * 100%); transition: flex-basis .5s var(--apl-week-ease); }
}
.apl-week .apl-week-keys {
  display: flex; align-items: center; gap: 8px; border: 0; background: none; padding: 4px 6px; font-size: 12px; color: var(--apl-week-mute); border-radius: 7px;
  &:hover { color: var(--apl-week-ink); background: var(--apl-week-line); }
}
.apl-week .apl-week-scrim { display: none; }

/* ── header ────────────────────────────────────────── */
.apl-week .apl-week-head {
  grid-area: head; display: flex; align-items: center; gap: 8px; padding: 12px 16px 12px 18px; min-width: 0;
  border-bottom: 1px solid var(--apl-week-line);
  & h2 {
    flex: 1; min-width: 0; margin-left: 6px; font-size: clamp(16px, 1.1cqi + 7px, 21px); font-weight: 720; letter-spacing: -.025em;
    font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-wrap: balance;
  }
  & h2 span { color: var(--apl-week-faint); font-weight: 500; }
}
.apl-week .apl-week-ib {
  display: grid; place-items: center; width: 32px; height: 32px; border: 0; border-radius: 8px; background: none; color: var(--apl-week-mute);
  transition: background .15s, color .15s;
  &:hover { background: var(--apl-week-line); color: var(--apl-week-ink); }
  &:disabled { opacity: .35; pointer-events: none; }
}
.apl-week .apl-week-menu, .apl-week .apl-week-plus { display: none; }
.apl-week .apl-week-plus { background: var(--apl-week-ink); color: var(--apl-week-bg); &:hover { background: color-mix(in oklch, var(--apl-week-ink) 85%, var(--apl-week-accent)); color: var(--apl-week-bg); } }
.apl-week .apl-week-today {
  display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px 0 12px; border-radius: 8px; font-weight: 600;
  border: 1px solid var(--apl-week-line2); background: var(--apl-week-surface);
  &:hover { border-color: var(--apl-week-faint); }
}
.apl-week .apl-week-step, .apl-week .apl-week-hist { display: flex; }
.apl-week .apl-week-views {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--apl-week-line);
  & button {
    display: flex; align-items: center; gap: 6px; border: 0; background: none; padding: 5px 7px 5px 11px; border-radius: 7px; font-weight: 600; font-size: 12.5px;
    color: var(--apl-week-mute); transition: background .2s, color .2s, box-shadow .2s;
    & kbd { background: none; border-color: transparent; }
  }
  & [aria-selected="true"] { background: var(--apl-week-surface); color: var(--apl-week-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--apl-week-ink) 18%, transparent); }
}

/* ── calendar grid (subgrid: header, all-day row and body share one column track list) ── */
.apl-week .apl-week-main { grid-area: main; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); position: relative; }
.apl-week .apl-week-strip { display: none; }
.apl-week .apl-week-scroll { min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apl-week-line2) transparent; position: relative; }
.apl-week .apl-week-cal {
  --gw: 56px;
  display: grid; grid-template-columns: var(--gw) repeat(var(--n, 7), minmax(0, 1fr)); min-width: 100%;
}
.apl-week .apl-week-top {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; position: sticky; top: 0; z-index: 6;
  background: color-mix(in oklch, var(--apl-week-bg) 92%, transparent); backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--apl-week-line2);
}
.apl-week .apl-week-tz { grid-column: 1; align-self: end; padding: 0 8px 8px 0; text-align: right; font: 600 9.5px ui-monospace, Menlo, monospace; color: var(--apl-week-faint); letter-spacing: .04em; }
.apl-week .apl-week-heads { grid-column: 2 / -1; display: grid; grid-template-columns: subgrid; }
.apl-week .apl-week-dh {
  display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto; align-items: end; column-gap: 7px; padding: 10px 10px 8px;
  border: 0; border-left: 1px solid var(--apl-week-line); background: none; text-align: left; min-width: 0;
  & .wd { grid-column: 1 / -1; font-size: 10px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--apl-week-mute); }
  & .dn { font-size: clamp(17px, 1.2cqi + 6px, 23px); font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & .ld { display: grid; gap: 3px; justify-items: end; padding-bottom: 3px; min-width: 0; }
  & .ld small { font: 500 10px ui-monospace, Menlo, monospace; color: var(--apl-week-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .ld i { width: 100%; max-width: 54px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--apl-week-accent) calc(var(--l) * 100%), var(--apl-week-line) 0); }
  &:hover .dn { color: var(--apl-week-accent); }
  &.is-today .wd { color: var(--apl-week-accent); }
  &.is-today .dn { color: var(--apl-week-accent); }
  &.is-wknd .wd, &.is-wknd .dn { opacity: .6; }
}
.apl-week .apl-week-adl { grid-column: 1; padding: 4px 8px 4px 0; text-align: right; font-size: 9.5px; font-weight: 600; color: var(--apl-week-faint); align-self: center; }
.apl-week .apl-week-allday {
  grid-column: 2 / -1; display: grid; grid-template-columns: subgrid; grid-auto-rows: 22px; row-gap: 3px; padding: 4px 0 6px; min-height: 32px;
  border-top: 1px solid var(--apl-week-line);
}
.apl-week .apl-week-ad {
  margin: 0 3px; padding: 0 8px; border: 0; border-radius: 5px; font-size: 11.5px; font-weight: 600; text-align: left; min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  background: color-mix(in oklab, var(--c) 22%, var(--apl-week-surface)); color: color-mix(in oklab, var(--c) 55%, var(--apl-week-ink));
  &.is-l { border-top-left-radius: 0; border-bottom-left-radius: 0; margin-left: 0; }
  &.is-r { border-top-right-radius: 0; border-bottom-right-radius: 0; margin-right: 0; }
  &:hover { background: color-mix(in oklab, var(--c) 32%, var(--apl-week-surface)); }
}

.apl-week .apl-week-body { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; height: calc(24 * var(--apl-week-hh)); position: relative; }
.apl-week .apl-week-gut {
  grid-column: 1; position: relative;
  & span { position: absolute; right: 8px; top: calc(var(--h) * var(--apl-week-hh)); translate: 0 -50%; font: 500 10px ui-monospace, Menlo, monospace; color: var(--apl-week-faint); font-variant-numeric: tabular-nums; }
}
.apl-week .apl-week-cols {
  grid-column: 2 / -1; display: grid; grid-template-columns: subgrid; position: relative;
  background:
    repeating-linear-gradient(to bottom, var(--apl-week-line) 0 1px, transparent 1px calc(var(--apl-week-hh) / 2), color-mix(in oklch, var(--apl-week-ink) 4.5%, transparent) calc(var(--apl-week-hh) / 2) calc(var(--apl-week-hh) / 2 + 1px), transparent calc(var(--apl-week-hh) / 2 + 1px) var(--apl-week-hh));
}
.apl-week .apl-week-col {
  position: relative; border-left: 1px solid var(--apl-week-line); min-width: 0; touch-action: pan-y;
  background: linear-gradient(to bottom, var(--apl-week-wash) calc(8 * var(--apl-week-hh)), transparent 0 calc(19 * var(--apl-week-hh)), var(--apl-week-wash) 0);
  background-blend-mode: multiply;
  &.is-wknd { background: color-mix(in oklch, var(--apl-week-ink) 2.5%, transparent); }
  &.is-today { background-color: color-mix(in oklab, var(--apl-week-accent) 3%, transparent); }
}

/* the event: positioned entirely from four custom properties set by the layout pass */
.apl-week .apl-week-ev {
  --d2: max(var(--d), 20);
  position: absolute; z-index: 1;
  top: calc(var(--t) * var(--apl-week-hh) / 60 + 1px);
  height: calc(var(--d2) * var(--apl-week-hh) / 60 - 2px);
  left: calc(var(--x) * 100% + 2px); width: calc(var(--w) * 100% - 5px);
  display: flex; flex-direction: column; gap: 1px; padding: 4px 7px; overflow: hidden; border-radius: 6px;
  background: color-mix(in oklab, var(--c) 14%, var(--apl-week-surface));
  color: color-mix(in oklab, var(--c) 42%, var(--apl-week-ink));
  box-shadow: inset 3px 0 0 var(--c), 0 0 0 1px var(--apl-week-surface);
  font-size: 11.5px; line-height: 1.25; cursor: grab; user-select: none; -webkit-user-select: none; touch-action: none;
  transition: background .18s, color .18s, box-shadow .25s, scale .3s var(--apl-week-spring), opacity .2s;
  & b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: var(--lines, 2); }
  & .tm { font: 500 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; opacity: .8; white-space: nowrap; }
  & .lc { font-size: 10.5px; opacity: .7; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .rz { position: absolute; left: 0; right: 0; bottom: 0; height: 7px; cursor: ns-resize; }
  & .rz::after { content: ""; position: absolute; left: 50%; bottom: 2px; width: 18px; height: 3px; translate: -50% 0; border-radius: 2px; background: currentColor; opacity: 0; transition: opacity .15s; }
  &:hover { background: color-mix(in oklab, var(--c) 22%, var(--apl-week-surface)); z-index: 2; }
  &:hover .rz::after { opacity: .35; }
  &.is-short { flex-direction: row; align-items: baseline; gap: 6px; padding-block: 1px; font-size: 10.5px; line-height: 1.2; }
  &.is-short b { -webkit-line-clamp: 1; flex: 0 1 auto; min-width: 0; display: block; white-space: nowrap; }
  &.is-short .tm { flex: 0 100 auto; min-width: 0; overflow: hidden; font-size: 10px; }
  &.is-short .lc, &.is-mid .lc { display: none; }
  &.is-sel { background: var(--c); color: oklch(0.99 0.01 85); box-shadow: 0 0 0 1px var(--apl-week-surface), 0 8px 22px -10px color-mix(in oklab, var(--c) 80%, black); z-index: 3; }
  &.is-sel .tm, &.is-sel .lc { opacity: .92; }
  &.is-drag { z-index: 5; cursor: grabbing; scale: 1.025; box-shadow: inset 3px 0 0 var(--c), 0 14px 30px -12px color-mix(in oklch, var(--apl-week-ink) 55%, transparent); transition: scale .3s var(--apl-week-spring), box-shadow .25s; }
  &.is-draft { background: color-mix(in oklab, var(--c) 20%, var(--apl-week-surface)); box-shadow: inset 0 0 0 1.5px var(--c); }
  &.is-draft b:empty::before { content: "(No title)"; opacity: .7; }
  &.is-in { animation: apl-week-in .5s var(--apl-week-ease) both; animation-delay: calc(var(--i, 0) * 14ms); }
}
.apl-week .apl-week-origin {
  position: absolute; z-index: 0; pointer-events: none; border-radius: 6px; border: 1.5px dashed color-mix(in oklab, var(--c) 60%, transparent);
  top: calc(var(--t) * var(--apl-week-hh) / 60 + 1px); height: calc(max(var(--d), 20) * var(--apl-week-hh) / 60 - 2px);
  left: calc(var(--x) * 100% + 2px); width: calc(var(--w) * 100% - 5px);
}
.apl-week .apl-week-hint {
  position: absolute; left: 2px; right: 3px; height: calc(var(--apl-week-hh) / 2 - 2px); top: calc(var(--t) * var(--apl-week-hh) / 60 + 1px);
  border-radius: 6px; background: color-mix(in oklab, var(--apl-week-accent) 9%, transparent); pointer-events: none; z-index: 0;
  padding: 2px 7px; font: 600 10.5px ui-monospace, Menlo, monospace; color: var(--apl-week-accent); opacity: 0; transition: opacity .15s;
  &.is-on { opacity: 1; }
}
.apl-week .apl-week-now {
  position: absolute; left: -1px; right: 0; top: calc(var(--m) * var(--apl-week-hh) / 60); height: 2px; z-index: 4; pointer-events: none;
  background: var(--apl-week-accent);
  &::before { content: ""; position: absolute; left: -5px; top: -4px; width: 10px; height: 10px; border-radius: 50%; background: var(--apl-week-accent); box-shadow: 0 0 0 3px var(--apl-week-bg); }
}
.apl-week .apl-week-nowall { position: absolute; left: 0; right: 0; top: calc(var(--m) * var(--apl-week-hh) / 60); border-top: 1px dashed color-mix(in oklab, var(--apl-week-accent) 45%, transparent); pointer-events: none; z-index: 0; }
.apl-week .apl-week-nowlab {
  position: absolute; right: 4px; top: calc(var(--m) * var(--apl-week-hh) / 60); translate: 0 -50%; z-index: 5;
  font: 700 10px ui-monospace, Menlo, monospace; color: oklch(0.99 0 0); background: var(--apl-week-accent); padding: 2px 4px; border-radius: 4px; font-variant-numeric: tabular-nums;
}
.apl-week.is-dragging, .apl-week.is-dragging * { cursor: grabbing; }
.apl-week.is-sizing, .apl-week.is-sizing * { cursor: ns-resize; }
.apl-week.is-creating .apl-week-cols { cursor: crosshair; }

/* ── event card / sheet ───────────────────────────────── */
.apl-week .apl-week-pop {
  position: absolute; z-index: 20; left: var(--px, 50%); top: var(--py, 50%); width: 300px; display: none;
  background: var(--apl-week-surface); border-radius: 14px; padding: 14px;
  box-shadow: 0 0 0 1px var(--apl-week-line), 0 24px 48px -18px color-mix(in oklch, var(--apl-week-ink) 45%, transparent), 0 2px 6px color-mix(in oklch, var(--apl-week-ink) 8%, transparent);
  transform-origin: var(--ox, left) top;
  transition: opacity .2s ease-out, scale .35s var(--apl-week-spring), translate .35s var(--apl-week-spring);
  &.is-on { display: block; }
