/* ── Fieldnote · week view ─────────────────────────────────────────────
   State lives in E (timed events) and A (all-day events); every gesture
   mutates a draft of that state, the layout pass re-derives positions, and
   commits push a snapshot so undo/redo is exact. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const SPRING = 'linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
$$('[data-mod]').forEach(k => { k.textContent = MAC ? '⌘' : 'Ctrl'; });

/* dates are integer epoch days, so a DST change can never move a column */
const DAY = 864e5;
const D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const monday = n => n - (dow(n) + 6) % 7;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const TODAY = D(2026, 10, 2);
const p2 = n => String(n).padStart(2, '0');
const hm = m => m >= 1440 ? '24:00' : p2(Math.floor(m / 60)) + ':' + p2(m % 60);
const dur = m => { const h = Math.floor(m / 60), r = m % 60; return ((h ? h + 'h' : '') + (h && r ? ' ' : '') + (r ? r + 'm' : '')) || '0m'; };
const dayLabel = n => { const [, mo, d] = ymd(n); return WD[dow(n)] + ', ' + MONTHS[mo].slice(0, 3) + ' ' + d; };
const isoWeek = n => { const th = monday(n) + 3; const [y] = ymd(th); return 1 + Math.floor((th - D(y, 1, 1)) / 7); };
const tm = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };

/* ── data ── */
const CALS = [
  { id: 'work', name: 'Studio', c: 'var(--apl-week-accent)' },
  { id: 'crit', name: 'Design crits', c: 'oklch(0.58 0.1 200)' },
  { id: 'hire', name: 'Hiring', c: 'oklch(0.7 0.14 72)' },
  { id: 'life', name: 'Personal', c: 'oklch(0.6 0.12 145)' },
  { id: 'trip', name: 'Travel', c: 'oklch(0.52 0.1 265)' },
];
const CAL = Object.fromEntries(CALS.map(c => [c.id, c]));
const PEOPLE = { io: 'Ines Okafor', tw: 'Tomasz Wierzbicki', ab: 'Ama Boateng', rq: 'Rosa Quintero', jp: 'Joon Park', lf: 'Lena Fischer', mr: 'Mateus Rocha', od: 'Odile Marchand', bs: 'Bruno Sá', kp: 'Kestrel Print team', fm: 'Ferro Metalworks' };
let seq = 0;
const mk = (day, s, e, cal, title, loc, who) => ({ id: 'e' + (++seq), day, s: tm(s), e: tm(e), cal, title, loc: loc || '', who: who || ['io'] });
let E = [];
let A = [];
(function seed() {
  for (let d = D(2026, 8, 31); d <= D(2026, 11, 1); d++) {
    const w = dow(d);
    if (w >= 1 && w <= 5) E.push(mk(d, '9:30', '9:45', 'work', 'Studio standup', 'Loft table', ['io', 'tw', 'ab', 'rq']));
    if (w === 2 || w === 4) E.push(mk(d, '8:00', '10:00', 'work', 'Deep work · no meetings', '', ['io']));
    if (w === 3) E.push(mk(d, '11:00', '11:30', 'work', '1:1 · Rosa Quintero', 'Window booth', ['io', 'rq']));
  }
  const W = D(2026, 9, 28);
  [
    [0, '10:30', '12:00', 'crit', 'Wayfinding crit — Harbor Library', 'Crit room', ['io', 'tw', 'ab']],
    [0, '12:30', '13:30', 'life', 'Lunch with Odile', 'Tasca do Lado', ['io', 'od']],
    [0, '14:00', '15:00', 'work', 'Kestrel Print — proof review', 'Video call', ['io', 'kp', 'tw']],
    [0, '14:30', '15:15', 'hire', 'Portfolio review: Joon Park', 'Small room', ['io', 'ab', 'jp']],
    [0, '16:00', '17:30', 'work', 'Signage spec writing', '', ['io']],
    [1, '11:00', '12:00', 'work', 'Brand system sync', 'Loft table', ['io', 'tw', 'ab', 'rq']],
    [1, '13:00', '14:00', 'hire', 'Interview: Lena Fischer, Sr. Designer', 'Small room', ['io', 'ab', 'lf']],
    [1, '13:30', '14:30', 'work', 'Supplier call — Ferro Metalworks', 'Video call', ['io', 'fm']],
    [1, '14:00', '14:30', 'hire', 'Recruiter debrief', 'Phone', ['io']],
    [1, '18:00', '19:30', 'life', 'Climbing — Gravity Wall', 'Gravity Wall, Marvila', ['io', 'bs']],
    [2, '10:00', '11:00', 'work', 'Harbor Library — client presentation', 'Harbor Library, Room 2', ['io', 'tw', 'rq']],
    [2, '15:00', '16:30', 'crit', 'Crit: museum map, iteration 3', 'Crit room', ['io', 'tw', 'ab']],
    [2, '17:00', '17:45', 'life', 'Dentist', 'Clínica Alvalade', ['io']],
    [3, '10:30', '11:30', 'hire', 'Hiring panel calibration', 'Small room', ['io', 'ab', 'rq']],
    [3, '12:00', '13:00', 'work', 'Team lunch — new joiners', 'Cantina Zero', ['io', 'tw', 'ab', 'rq']],
    [3, '14:00', '16:00', 'work', 'Lisbon offsite planning', 'Loft table', ['io', 'rq']],
    [3, '15:00', '15:30', 'work', 'Call with Kestrel Print', 'Phone', ['io', 'kp']],
    [3, '19:00', '21:00', 'life', 'Fado night with Odile & Bruno', 'Tasca da Rua', ['io', 'od', 'bs']],
    [4, '10:00', '11:00', 'crit', 'Weekly design review', 'Crit room', ['io', 'tw', 'ab']],
    [4, '11:30', '12:15', 'hire', 'Interview: Mateus Rocha, Junior', 'Video call', ['io', 'mr']],
    [4, '13:00', '14:00', 'life', 'Lunch & walk', 'Jardim da Estrela', ['io']],
    [4, '14:30', '15:30', 'work', 'Studio retro', 'Loft table', ['io', 'tw', 'ab', 'rq']],
    [4, '16:00', '17:00', 'work', 'Ship: wayfinding v2 package', '', ['io', 'tw']],
    [5, '10:00', '12:00', 'life', 'Farmers market & bakery', 'Mercado de Campo de Ourique', ['io']],
    [6, '15:00', '16:00', 'life', 'Call Mum', '', ['io']],
  ].forEach(r => E.push(mk(W + r[0], r[1], r[2], r[3], r[4], r[5], r[6])));
  /* other weeks: a seeded, deterministic sample so navigation never lands on an empty grid */
  const POOL = [
    ['crit', 'Crit: transit map legibility', 'Crit room', 90], ['crit', 'Type pairing review', 'Crit room', 60],
    ['work', 'Kestrel Print — press check', 'Kestrel Print, Marvila', 120], ['work', 'Client sync · Harbor Library', 'Video call', 45],
    ['work', 'Budget review with Rosa', 'Window booth', 30], ['hire', 'Portfolio review', 'Video call', 45],
    ['hire', 'Interview loop debrief', 'Small room', 30], ['work', 'Signage install walk-through', 'Harbor Library', 120],
    ['crit', 'Icon set crit', 'Crit room', 60], ['work', 'Proposal writing — Tagus Ferries', '', 90],
  ];
  const SLOTS = [600, 690, 780, 840, 930, 990];
  let r = 7;
  const rnd = () => (r = (r * 16807) % 2147483647) / 2147483647;
  for (let d = D(2026, 8, 31); d <= D(2026, 11, 1); d++) {
    if (d >= W && d < W + 7) continue;
    const w = dow(d);
    if (w === 0 || w === 6) { if (rnd() < .45) E.push(mk(d, '11:00', '12:30', 'life', rnd() < .5 ? 'Long run by the river' : 'Brunch with Bruno', '', ['io'])); continue; }
    const used = new Set(), k = 1 + Math.floor(rnd() * 3);
    for (let j = 0; j < k; j++) {
      const p = POOL[Math.floor(rnd() * POOL.length)], s = SLOTS[Math.floor(rnd() * SLOTS.length)];
      if (used.has(s)) continue; used.add(s);
      E.push({ id: 'e' + (++seq), day: d, s, e: s + p[3], cal: p[0], title: p[1], loc: p[2], who: ['io', 'tw'] });
    }
    if (w === 2 && rnd() < .6) E.push(mk(d, '18:00', '19:30', 'life', 'Climbing — Gravity Wall', 'Gravity Wall, Marvila', ['io', 'bs']));
  }
  let a = 0;
  const ad = (day, len, cal, title) => A.push({ id: 'a' + (++a), day, len, cal, title });
  ad(D(2026, 9, 21), 5, 'work', 'Kestrel Print — proofing week');
  ad(D(2026, 9, 28), 2, 'work', 'Rosa away · conference');
  ad(D(2026, 9, 30), 3, 'crit', 'Lisbon Design Week');
  ad(D(2026, 10, 4), 1, 'life', 'Odile’s birthday');
  ad(D(2026, 10, 5), 1, 'work', 'Studio closed · public holiday');
  ad(D(2026, 10, 7), 3, 'trip', 'Porto — signage install');
  ad(D(2026, 10, 16), 1, 'trip', 'Train to Coimbra');
})();

/* ── state ── */
const S = { anchor: TODAY, view: 'week', narrow: false, hidden: new Set(), sel: null, mini: null, lastCal: 'work' };
const past = [], future = [];
const snapshot = () => structuredClone({ E: E.filter(x => !x.draft), A });
const find = id => E.find(x => x.id === id);
const days = () => (S.view === 'day' || S.narrow) ? [S.anchor] : Array.from({ length: 7 }, (_, i) => monday(S.anchor) + i);
const hh = () => parseFloat(getComputedStyle(root).getPropertyValue('--apl-week-hh')) || 48;

/* ── elements ── */
const calEl = $('[data-cal]'), heads = $('[data-heads]'), alldayEl = $('[data-allday]'), cols = $('[data-cols]'), gut = $('[data-gut]');
const scroller = $('[data-scroll]'), pop = $('[data-pop]'), help = $('[data-help]'), toastEl = $('[data-toast]'), strip = $('[data-strip]');
gut.innerHTML = Array.from({ length: 23 }, (_, i) => '<span style="--h:' + (i + 1) + '">' + p2(i + 1) + ':00</span>').join('') + '<span class="apl-week-nowlab" data-nowlab></span>';
const nowLab = $('[data-nowlab]');
const hint = doc.createElement('div'); hint.className = 'apl-week-hint'; hint.setAttribute('aria-hidden', 'true');
const origin = doc.createElement('div'); origin.className = 'apl-week-origin';
let colKey = '', colEls = [];
const nodes = new Map();

/* ── overlap layout: collision clusters → greedy columns → expand right ── */
function layout(list) {
  const out = new Map();
  let cluster = [], colz = [], end = -1;
  const flush = () => {
    const n = colz.length;
    cluster.forEach(o => {
      let span = 1;
      for (let c = o.col + 1; c < n; c++) {
        if (colz[c].some(x => x.s < o.ev.e && x.e > o.ev.s)) break;
        span++;
      }
      out.set(o.ev.id, { col: o.col, n, span });
    });
    cluster = []; colz = [];
  };
  for (const ev of list) {
    if (ev.s >= end && cluster.length) flush();
    let c = colz.findIndex(col => col[col.length - 1].e <= ev.s);
    if (c < 0) { c = colz.length; colz.push([]); }
    colz[c].push(ev); cluster.push({ ev, col: c });
    end = Math.max(end, ev.e);
  }
  if (cluster.length) flush();
  return out;
}

function minsOn(d) { return E.filter(e => e.day === d && !S.hidden.has(e.cal) && !e.draft).reduce((t, e) => t + e.e - e.s, 0); }

function buildCols(ds) {
  const key = ds.join(',') + (S.narrow ? 'n' : '');
  if (key === colKey) return false;
  colKey = key;
  calEl.style.setProperty('--n', ds.length);
  cols.innerHTML = ds.map(d => '<div class="apl-week-col' + (d === TODAY ? ' is-today' : '') + (dow(d) % 6 === 0 ? ' is-wknd' : '') + '" data-day="' + d + '"></div>').join('') + '<div class="apl-week-nowall" data-nowall style="grid-column:1/-1;grid-row:1"></div>';
  colEls = $$('.apl-week-col', cols);
  return true;
}

function nodeFor(ev) {
  let n = nodes.get(ev.id);
  if (!n) {
    n = doc.createElement('div'); n.className = 'apl-week-ev'; n.tabIndex = 0;
