.apl-month {
  /* theme: four variables re-skin the whole board */
  --apl-month-bg: oklch(0.195 0.006 85);
  --apl-month-ink: oklch(0.95 0.01 95);
  --apl-month-accent: oklch(0.89 0.19 124);
  --apl-month-panel: oklch(0.225 0.007 85);
  --apl-month-line: color-mix(in oklch, var(--apl-month-ink) 9%, transparent);
  --apl-month-line2: color-mix(in oklch, var(--apl-month-ink) 16%, transparent);
  --apl-month-mute: color-mix(in oklch, var(--apl-month-ink) 58%, var(--apl-month-bg));
  --apl-month-faint: color-mix(in oklch, var(--apl-month-ink) 34%, var(--apl-month-bg));
  --apl-month-raise: color-mix(in oklch, var(--apl-month-ink) 5%, var(--apl-month-bg));
  --apl-month-on-accent: oklch(0.22 0.04 125);
  --apl-month-ease: cubic-bezier(.2, .8, .2, 1);
  --apl-month-spring: linear(0, 0.08 4%, 0.32 9%, 0.66 15%, 0.92 22%, 1.05 28%, 1.08 33%, 1.05 39%, 1.01 48%, 0.995 60%, 1);
  --apl-month-lane: 19px;

  position: relative; width: 100%; height: var(--apl-month-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-month-bg); color: var(--apl-month-ink); color-scheme: dark; accent-color: var(--apl-month-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-month-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; text-align: center; display: inline-block;
    border: 1px solid var(--apl-month-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-month-mute);
  }
}
.apl-month .apl-month-app {
  height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 288px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head" "main side";
}

/* ── header ── */
.apl-month .apl-month-head {
  grid-area: head; display: grid; grid-template-columns: auto auto minmax(220px, 1fr) auto; grid-template-areas: "ttl nav qa tabs";
  align-items: center; gap: 12px 18px; padding: 18px 20px 14px;
}
.apl-month .apl-month-ttl {
  grid-area: ttl; min-width: 0;
  & h2 { font-size: clamp(22px, 2.2cqi + 6px, 34px); font-weight: 760; letter-spacing: -.035em; line-height: 1; white-space: nowrap; text-wrap: balance; }
  & h2 span { font-weight: 300; color: var(--apl-month-faint); margin-left: .18em; font-variant-numeric: tabular-nums; }
  & p { margin-top: 6px; font-size: 11px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--apl-month-mute); }
}
.apl-month .apl-month-nav { grid-area: nav; display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 11px; background: var(--apl-month-raise); box-shadow: inset 0 0 0 1px var(--apl-month-line); }
.apl-month .apl-month-ib {
  display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 8px; background: none; color: var(--apl-month-mute);
  transition: background .15s, color .15s;
  &:hover { background: var(--apl-month-line); color: var(--apl-month-ink); }
}
.apl-month .apl-month-today {
  display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 8px 0 10px; border: 0; border-radius: 8px; background: none; font-weight: 650; font-size: 12.5px;
  &:hover { background: var(--apl-month-line); }
}
.apl-month .apl-month-qa {
  grid-area: qa; position: relative; display: flex; align-items: center; gap: 9px; height: 40px; padding: 0 8px 0 12px; border-radius: 12px; min-width: 0;
  background: var(--apl-month-raise); box-shadow: inset 0 0 0 1px var(--apl-month-line);
  transition: box-shadow .2s, background .2s;
  & > svg { color: var(--apl-month-accent); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 13.5px; }
  & input::placeholder { color: var(--apl-month-faint); }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apl-month-accent), 0 0 0 4px color-mix(in oklab, var(--apl-month-accent) 14%, transparent); background: var(--apl-month-panel); }
  &:focus-within > kbd { opacity: 0; }
}
.apl-month .apl-month-parse {
  position: absolute; z-index: 12; left: 0; right: 0; top: calc(100% + 8px); display: none; padding: 10px; border-radius: 12px;
  background: var(--apl-month-panel); box-shadow: 0 0 0 1px var(--apl-month-line2), 0 20px 40px -16px oklch(0 0 0 / .7);
  &.is-on { display: block; }
  @starting-style { &.is-on { opacity: 0; translate: 0 -4px; } }
  transition: opacity .18s, translate .3s var(--apl-month-ease);
  & .apl-month-toks { display: flex; flex-wrap: wrap; gap: 6px; }
  & .tok {
    display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px; border-radius: 7px; font-size: 12px; font-weight: 600;
    background: var(--apl-month-line); color: var(--apl-month-ink); animation: apl-month-pop .35s var(--apl-month-spring) both; animation-delay: calc(var(--i, 0) * 40ms);
    & small { font-weight: 700; font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--apl-month-mute); }
    & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  }
  & .tok.is-title { background: none; box-shadow: inset 0 0 0 1px var(--apl-month-line2); }
  & p { margin-top: 9px; font-size: 11.5px; color: var(--apl-month-mute); display: flex; gap: 6px; align-items: center; text-wrap: pretty; }
}
.apl-month .apl-month-tabs {
  grid-area: tabs; display: none; padding: 3px; gap: 2px; border-radius: 10px; background: var(--apl-month-raise);
  & button { border: 0; background: none; border-radius: 7px; padding: 6px 12px; font-weight: 650; font-size: 12.5px; color: var(--apl-month-mute); transition: background .2s, color .2s; }
  & [aria-selected="true"] { background: var(--apl-month-ink); color: var(--apl-month-bg); }
}

/* ── month grid: day-of-week header and every week row share one 7-track grid via subgrid ── */
.apl-month .apl-month-main {
  grid-area: main; min-height: 0; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-template-rows: auto minmax(0, 1fr);
  padding: 0 0 12px 12px;
}
.apl-month .apl-month-dow {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding-bottom: 6px;
  & span { padding: 0 10px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apl-month-faint); }
}
.apl-month .apl-month-grid {
  grid-column: 1 / -1; min-height: 0; display: grid; grid-template-columns: subgrid; grid-template-rows: repeat(var(--weeks, 5), minmax(0, 1fr));
  border-radius: 12px; box-shadow: inset 0 0 0 1px var(--apl-month-line); overflow: clip;
}
.apl-month .apl-month-week {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; grid-template-rows: 28px repeat(var(--lanes, 3), var(--apl-month-lane)) minmax(0, 1fr);
  row-gap: 1px; min-height: 0; position: relative;
  & + .apl-month-week { border-top: 1px solid var(--apl-month-line); }
}
.apl-month .apl-month-cell {
  grid-row: 1 / -1; position: relative; z-index: 0; padding: 6px 9px; min-width: 0; outline-offset: -2px;
  transition: background .2s;
