/* ── Quarry Labs · month board ─────────────────────────────────────────
   Every week row is its own 7-column subgrid. Events are packed into lanes
   per week and placed with grid-column spans; the number of lanes that fit
   is measured, and anything past it collapses into "+N more". */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.08 4%, 0.32 9%, 0.66 15%, 0.92 22%, 1.05 28%, 1.08 33%, 1.05 39%, 1.01 48%, 0.995 60%, 1)';
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
$$('[data-mod]').forEach(k => { k.textContent = MAC ? '\u2318' : 'Ctrl'; });

const DAY = 864e5;
const D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const monday = n => n - (dow(n) + 6) % 7;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const TODAY = D(2026, 10, 2);
const p2 = n => String(n).padStart(2, '0');
const hm = m => p2(Math.floor(m / 60) % 24) + ':' + p2(m % 60);
const short = n => { const [, m, d] = ymd(n); return WD[dow(n)] + ', ' + MONTHS[m].slice(0, 3) + ' ' + d; };
const md = n => { const [, m, d] = ymd(n); return MONTHS[m].slice(0, 3) + ' ' + d; };

/* ── data ── */
const CALS = [
  { id: 'rel', name: 'Releases', c: 'var(--apl-month-accent)', tags: ['release', 'rel', 'ship', 'releases'] },
  { id: 'onc', name: 'On-call', c: 'oklch(0.8 0.14 70)', tags: ['oncall', 'on-call', 'pager'] },
  { id: 'team', name: 'Team', c: 'oklch(0.76 0.1 232)', tags: ['team', 'mtg', 'meeting'] },
  { id: 'ooo', name: 'Out of office', c: 'oklch(0.72 0.13 12)', tags: ['ooo', 'away', 'pto', 'leave'] },
  { id: 'evt', name: 'Events', c: 'oklch(0.78 0.09 180)', tags: ['event', 'events', 'conf'] },
];
const CAL = Object.fromEntries(CALS.map(c => [c.id, c]));
let seq = 0;
let E = [];
const add = (day, len, cal, title, s, e) => E.push({ id: 'm' + (++seq), day, len: len || 1, cal, title, s: s == null ? null : s, e: e == null ? null : e });
(function seed() {
  const rot = [['Ola Nwosu', 9, 7], ['Marcus Holt', 9, 14], ['Dana Kerr', 9, 21], ['Priya Raman', 9, 28], ['Marcus Holt', 10, 5], ['Dana Kerr', 10, 12], ['Ola Nwosu', 10, 19], ['Priya Raman', 10, 26], ['Marcus Holt', 11, 2], ['Dana Kerr', 11, 9], ['Ola Nwosu', 11, 16], ['Priya Raman', 11, 23]];
  rot.forEach(([n, m, d]) => add(D(2026, m, d), 7, 'onc', 'On-call \u00b7 ' + n));
  [[9, 23, '4.11'], [10, 7, '4.12'], [10, 21, '4.13'], [11, 4, '4.14'], [11, 18, '4.15']].forEach(([m, d, v]) => {
    add(D(2026, m, d), 1, 'rel', 'Release ' + v);
    add(D(2026, m, d) - 2, 2, 'rel', v + ' code freeze');
  });
  for (let d = D(2026, 9, 3); d <= D(2026, 11, 26); d += 7) add(d, 1, 'team', 'Design review', 840, 900);
  [[9, 21, 40], [10, 5, 41], [10, 19, 42], [11, 2, 43], [11, 16, 44]].forEach(([m, d, n]) => add(D(2026, m, d), 1, 'team', 'Sprint ' + n + ' planning', 600, 690));
  [[10, 2, 40], [10, 16, 41], [10, 30, 42], [11, 13, 43]].forEach(([m, d, n]) => add(D(2026, m, d), 1, 'team', 'Sprint ' + n + ' retro', 900, 960));
  add(D(2026, 10, 2), 1, 'team', 'Postmortem: checkout latency', 660, 720);
  add(D(2026, 10, 8), 1, 'team', 'All-hands', 1020, 1080);
  add(D(2026, 10, 14), 1, 'team', 'Arch review: event bus', 780, 870);
  add(D(2026, 10, 22), 1, 'evt', 'Customer advisory board', 780, 900);
  add(D(2026, 9, 30), 1, 'team', 'Q4 OKR draft due', 1020, 1050);
  add(D(2026, 10, 19), 26, 'ooo', 'Jun Takeda \u00b7 parental leave');
  add(D(2026, 10, 12), 5, 'ooo', 'Ola \u00b7 Lisbon');
  add(D(2026, 10, 28), 3, 'ooo', 'Marcus out');
  add(D(2026, 10, 14), 2, 'evt', 'Platform Summit, Rotterdam');
  add(D(2026, 10, 26), 5, 'evt', 'Hack week');
  add(D(2026, 11, 11), 3, 'evt', 'Team offsite \u00b7 Sintra');
  add(D(2026, 9, 14), 3, 'ooo', 'Dana out');
})();

/* ── state ── */
const S = { month: D(2026, 10, 1), sel: TODAY, hidden: new Set(), lanes: 3, tab: 'month', ghost: null };
const past = [], future = [];
const snapshot = () => structuredClone(E);
const find = id => E.find(x => x.id === id);
const covers = (ev, d) => d >= ev.day && d < ev.day + ev.len;
const isBar = ev => ev.len > 1 || ev.s == null;
const visible = () => E.filter(ev => !S.hidden.has(ev.cal));
const order = (a, b) => (!!b.ghost - !!a.ghost) || (isBar(b) - isBar(a)) || a.day - b.day || b.len - a.len || (a.s || 0) - (b.s || 0);

const grid = $('[data-grid]'), qa = $('[data-qa]'), qi = $('[data-qi]'), parseEl = $('[data-parse]');
const more = $('[data-more]'), card = $('[data-card]'), toastEl = $('[data-toast]');

/* ── layout: lanes per week ── */
function weekLayout(ws, list) {
  const we = ws + 6;
  const items = list.filter(ev => ev.day <= we && ev.day + ev.len - 1 >= ws).sort(order);
  const occ = [];
  items.forEach(ev => {
    const sc = Math.max(ws, ev.day) - ws, ec = Math.min(we, ev.day + ev.len - 1) - ws;
    let l = 0;
    for (;; l++) { occ[l] = occ[l] || []; let free = true; for (let c = sc; c <= ec; c++) if (occ[l][c]) { free = false; break; } if (free) break; }
    for (let c = sc; c <= ec; c++) occ[l][c] = true;
    ev._l = { sc, ec, lane: l };
  });
  const L = S.lanes;
  const over = new Set();
  items.forEach(ev => { if (ev._l.lane >= L) for (let c = ev._l.sc; c <= ev._l.ec; c++) over.add(c); });
  const shown = [], hiddenBy = Array(7).fill(0);
  items.forEach(ev => {
    const { sc, ec, lane } = ev._l;
    let vis = lane < L - 1 || (lane === L - 1 && ![...Array(ec - sc + 1)].some((_, i) => over.has(sc + i)));
    if (!over.size) vis = lane < L;
    if (vis) shown.push(ev); else for (let c = sc; c <= ec; c++) hiddenBy[c]++;
  });
  return { shown, hiddenBy, over };
