const cellAt = (x, y) => { const el = doc.elementsFromPoint(x, y).find(n => n.classList && n.classList.contains('apl-month-cell') && root.contains(n)); return el ? +el.dataset.day : null; };
grid.addEventListener('pointerdown', e => {
  const it = e.target.closest('.apl-month-it');
  if (!it || e.button !== 0 || it.classList.contains('is-ghost')) return;
  const ev = find(it.dataset.id); if (!ev) return;
  e.preventDefault();
  drag = { id: ev.id, pid: e.pointerId, x0: e.clientX, y0: e.clientY, grab: cellAt(e.clientX, e.clientY), mode: e.target.closest('.rz') ? 'size' : 'move', snap: snapshot(), d0: ev.day, l0: ev.len, s0: ev.s, e0: ev.e, el: it, moved: false };
  grid.setPointerCapture(e.pointerId);
});
grid.addEventListener('pointermove', e => {
  if (!drag || e.pointerId !== drag.pid) return;
  if (!drag.moved && Math.hypot(e.clientX - drag.x0, e.clientY - drag.y0) < 5) return;
  const ev = find(drag.id);
  if (!drag.moved) {
    drag.moved = true; closeLayers();
    root.classList.add(drag.mode === 'size' ? 'is-sizing' : 'is-dragging');
    if (drag.mode === 'move') {
      const r = drag.el.getBoundingClientRect(), rr = root.getBoundingClientRect();
      const f = drag.el.cloneNode(true); f.classList.add('apl-month-float'); f.classList.remove('is-l', 'is-r', 'is-sel');
      f.style.width = Math.min(r.width, 220) + 'px'; f.style.gridRow = 'auto';
      drag.fx = r.left - rr.left; drag.fy = r.top - rr.top; drag.f = f; root.append(f);
      $$('.apl-month-it[data-id="' + ev.id + '"]', grid).forEach(x => x.classList.add('is-lift'));
    }
  }
  const at = cellAt(e.clientX, e.clientY);
  if (drag.mode === 'move') {
    drag.f.style.transform = 'translate(' + (drag.fx + e.clientX - drag.x0) + 'px,' + (drag.fy + e.clientY - drag.y0) + 'px)';
    if (at != null && drag.grab != null) {
      const s = drag.d0 + at - drag.grab;
      if (s !== drag.target) {
        drag.target = s;
        $$('.apl-month-cell', grid).forEach(c => { const d = +c.dataset.day; c.classList.toggle('is-drop', d >= s && d < s + ev.len); c.classList.toggle('is-drop-s', d === s); });
      }
    }
  } else if (at != null) {
    const len = Math.max(1, at - ev.day + 1);
    if (len !== ev.len) { ev.len = len; if (len > 1) { ev.s = null; ev.e = null; } else { ev.s = drag.s0; ev.e = drag.e0; } render(); }
  }
});
function endDrag(e, cancel) {
  if (!drag || e.pointerId !== drag.pid) return;
  const d = drag; drag = null;
  root.classList.remove('is-dragging', 'is-sizing');
  $$('.is-drop, .is-drop-s', grid).forEach(c => c.classList.remove('is-drop', 'is-drop-s'));
  const ev = find(d.id);
  if (!d.moved) { openCard(d.id, d.el); return; }
  if (d.mode === 'move') {
    const fr = d.f.getBoundingClientRect(); d.f.remove();
    const delta = cancel || d.target == null ? 0 : d.target - d.d0;
    if (!delta) { $$('.is-lift', grid).forEach(x => x.classList.remove('is-lift')); return; }
    ev.day += delta; S.sel = ev.day;
    flip(render, { id: ev.id, rect: fr });
