grid.addEventListener('pointerup', e => endDrag(e, false));
grid.addEventListener('pointercancel', e => endDrag(e, true));

/* ── clicks ── */
root.addEventListener('click', e => {
  const t = e.target;
  const act = t.closest('[data-act]'), cell = t.closest('.apl-month-cell'), mb = t.closest('[data-more]'), op = t.closest('[data-open]'), cb = t.closest('[data-cal]'), tab = t.closest('[data-tabv]');
  if (mb && mb.matches('.apl-month-mbtn')) { openMore(+mb.dataset.more, mb); return; }
  if (op) { openCard(op.dataset.open, op); return; }
  if (cb) { const id = cb.dataset.cal; S.hidden.has(id) ? S.hidden.delete(id) : S.hidden.add(id); flip(render); return; }
  if (tab) { setTab(tab.dataset.tabv); return; }
  if (cell && !t.closest('.apl-month-it')) {
    closeLayers(); S.sel = +cell.dataset.day; render();
    const c = $('[data-day="' + S.sel + '"]', grid); if (c) c.focus({ preventScroll: true });
    if (root.clientWidth < 760) setTab('day');
    return;
  }
  if (!act) { if (!t.closest('[data-card], [data-more], .apl-month-it')) closeLayers(); return; }
  const a = act.dataset.act;
  if (a === 'prev') stepMonth(-1);
  else if (a === 'next') stepMonth(1);
  else if (a === 'today') { S.sel = TODAY; setMonth(monthOf(TODAY), Math.sign(monthOf(TODAY) - S.month)); render(); }
  else if (a === 'undo') undo();
  else if (a === 'del') del(act.dataset.id);
  else if (a === 'push') push(act.dataset.id);
  else if (a === 'close') { closeLayers(); root.focus({ preventScroll: true }); }
});

/* ── keyboard ── */
root.addEventListener('keydown', e => {
  const k = e.key, mod = e.metaKey || e.ctrlKey, typing = e.target === qi;
  if (k === 'Escape') {
    if (typing) { qi.value = ''; updateQuick(); qi.blur(); select(S.sel, true); return; }
    if (card.classList.contains('is-on') || more.classList.contains('is-on')) { closeLayers(); select(S.sel, true); return; }
    return;
  }
  if (typing) return;
  if (mod && k.toLowerCase() === 'z') { e.preventDefault(); e.shiftKey ? redo() : undo(); return; }
  if (mod) return;
  if ((k === 'Delete' || k === 'Backspace') && (S.picked || e.target.closest('[data-open]'))) { e.preventDefault(); del(S.picked || e.target.closest('[data-open]').dataset.open); return; }
  const onCell = e.target.closest('.apl-month-cell');
  const moves = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 };
  if (k in moves && (onCell || e.target === root)) { e.preventDefault(); closeLayers(); select(S.sel + moves[k], true); return; }
  if (onCell && (k === 'Home' || k === 'End')) { e.preventDefault(); select(k === 'Home' ? monday(S.sel) : monday(S.sel) + 6, true); return; }
  if (onCell && k === 'Enter') {
    e.preventDefault();
    if (root.clientWidth < 960) setTab('day');
    const f = $('[data-agenda] button'); if (f) f.focus({ preventScroll: true });
    return;
  }
  const key = k.length === 1 ? k.toLowerCase() : k;
  if (key === 'n' || key === '/') { e.preventDefault(); if (S.tab !== 'month' && root.clientWidth < 960) setTab('month'); qi.focus(); }
  else if (key === 't') { S.sel = TODAY; setMonth(monthOf(TODAY), Math.sign(monthOf(TODAY) - S.month)); select(TODAY, true); }
  else if (key === 'j' || k === 'PageDown') { e.preventDefault(); stepMonth(1); select(S.sel, true); }
  else if (key === 'k' || k === 'PageUp') { e.preventDefault(); stepMonth(-1); select(S.sel, true); }
});
root.addEventListener('animationend', e => { if (e.animationName === 'apl-month-land') e.target.classList.remove('is-new'); });

const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  measure();
  if (root.clientWidth >= 960 && S.tab !== 'month') setTab('month');
