@property --apl-plan-p { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --apl-plan-n { syntax: '<integer>'; inherits: true; initial-value: 0; }

.apl-plan {
  /* theme */
  --apl-plan-bg: oklch(0.972 0.01 112);
  --apl-plan-ink: oklch(0.27 0.035 158);
  --apl-plan-accent: oklch(0.56 0.1 158);
  --apl-plan-surface: oklch(0.994 0.004 112);
  --apl-plan-hh: 60px;
  --apl-plan-line: color-mix(in oklch, var(--apl-plan-ink) 10%, transparent);
  --apl-plan-line2: color-mix(in oklch, var(--apl-plan-ink) 18%, transparent);
  --apl-plan-mute: color-mix(in oklch, var(--apl-plan-ink) 58%, var(--apl-plan-bg));
  --apl-plan-faint: color-mix(in oklch, var(--apl-plan-ink) 36%, var(--apl-plan-bg));
  --apl-plan-wash: color-mix(in oklch, var(--apl-plan-ink) 4%, var(--apl-plan-bg));
  --apl-plan-ease: cubic-bezier(.22, .9, .25, 1);
  --apl-plan-spring: linear(0, 0.1 4%, 0.36 9%, 0.7 15%, 0.94 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1);

  position: relative; width: 100%; height: var(--apl-plan-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-plan-bg); color: var(--apl-plan-ink); color-scheme: light; accent-color: var(--apl-plan-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px;
  box-shadow: 0 0 0 1px var(--apl-plan-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-plan-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; display: inline-block; text-align: center;
    border: 1px solid var(--apl-plan-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-plan-mute); background: var(--apl-plan-surface);
  }
}
.apl-plan .apl-plan-app {
  height: 100%; display: grid; grid-template-columns: 300px minmax(0, 1fr) 264px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head head" "inbox day sum";
}

/* ── header ── */
.apl-plan .apl-plan-head {
  grid-area: head; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "date cap acts";
  gap: 12px 28px; align-items: center; padding: 18px 20px 16px; border-bottom: 1px solid var(--apl-plan-line);
}
.apl-plan .apl-plan-date {
  grid-area: date;
  & p { font-size: 11px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--apl-plan-mute); }
  & h2 { margin-top: 3px; font-size: clamp(20px, 1.6cqi + 8px, 28px); font-weight: 400; letter-spacing: -.025em; line-height: 1.1; white-space: nowrap; text-wrap: balance; }
  & h2 span { font-weight: 760; }
}
.apl-plan .apl-plan-cap {
  grid-area: cap; justify-self: center; width: min(100%, 460px); display: grid; gap: 7px;
  & .apl-plan-meter { display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px; background: var(--apl-plan-line); }
  & .apl-plan-meter i { flex: 0 0 auto; width: calc(var(--w) * 100%); background: var(--c); transition: width .7s var(--apl-plan-ease); }
  & .apl-plan-meter i.mt { background: repeating-linear-gradient(-45deg, var(--apl-plan-faint) 0 3px, color-mix(in oklch, var(--apl-plan-faint) 55%, transparent) 3px 6px); }
  & .lg { display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 11.5px; color: var(--apl-plan-mute); }
  & .lg span { display: inline-flex; align-items: center; gap: 6px; }
  & .lg b { color: var(--apl-plan-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .lg i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & .lg i.mt { background: repeating-linear-gradient(-45deg, var(--apl-plan-faint) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--apl-plan-faint); }
  & .lg .of { margin-left: auto; }
}
.apl-plan .apl-plan-acts { grid-area: acts; display: flex; align-items: center; gap: 4px; }
.apl-plan .apl-plan-ib {
  display: grid; place-items: center; width: 34px; height: 34px; border: 0; border-radius: 10px; background: none; color: var(--apl-plan-mute);
  transition: background .15s, color .15s;
  &:hover { background: var(--apl-plan-line); color: var(--apl-plan-ink); }
  &:disabled { opacity: .35; pointer-events: none; }
}
.apl-plan .apl-plan-auto {
  display: flex; align-items: center; gap: 8px; height: 36px; margin-left: 6px; padding: 0 9px 0 12px; border: 0; border-radius: 11px;
  background: var(--apl-plan-ink); color: var(--apl-plan-bg); font-weight: 650; font-size: 12.5px;
  box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--apl-plan-ink) 70%, transparent);
  transition: scale .3s var(--apl-plan-spring), background .2s;
  & svg { color: color-mix(in oklab, var(--apl-plan-accent) 60%, white); }
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--apl-plan-bg) 35%, transparent); }
  &:hover { background: color-mix(in oklch, var(--apl-plan-ink) 85%, var(--apl-plan-accent)); }
  &:hover svg { rotate: 90deg; }
  & svg { transition: rotate .6s var(--apl-plan-spring); }
  &:active { scale: .97; }
}
.apl-plan .apl-plan-tabs {
  grid-area: tabs; display: none; padding: 3px; gap: 2px; border-radius: 11px; background: var(--apl-plan-line);
  & button { flex: 1; border: 0; background: none; padding: 7px 10px; border-radius: 8px; font-weight: 650; font-size: 12.5px; color: var(--apl-plan-mute); transition: background .2s, color .2s; }
  & b { font-weight: 650; font-size: 11px; padding: 1px 6px; border-radius: 8px; background: var(--apl-plan-line); font-variant-numeric: tabular-nums; }
  & [aria-selected="true"] { background: var(--apl-plan-surface); color: var(--apl-plan-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--apl-plan-ink) 15%, transparent); }
}

/* ── inbox ── */
.apl-plan .apl-plan-inbox {
  grid-area: inbox; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; gap: 10px; padding: 14px 12px 12px 16px;
  border-right: 1px solid var(--apl-plan-line);
}
.apl-plan .apl-plan-add {
  display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 8px 0 11px; border-radius: 11px; background: var(--apl-plan-surface);
  box-shadow: 0 0 0 1px var(--apl-plan-line2); transition: box-shadow .2s;
  & svg { color: var(--apl-plan-accent); }
  & input { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font-size: 13px; }
  & input::placeholder { color: var(--apl-plan-faint); }
  &:focus-within { box-shadow: 0 0 0 1.5px var(--apl-plan-accent), 0 0 0 5px color-mix(in oklab, var(--apl-plan-accent) 14%, transparent); }
  &:focus-within kbd { opacity: 0; }
}
.apl-plan .apl-plan-filter {
  display: flex; gap: 4px;
  & button { border: 0; border-radius: 20px; padding: 4px 10px; background: none; font-size: 12px; font-weight: 600; color: var(--apl-plan-mute); transition: background .2s, color .2s; }
  & button span { font-variant-numeric: tabular-nums; color: var(--apl-plan-faint); margin-left: 3px; }
  & button:hover { background: var(--apl-plan-line); }
  & [aria-pressed="true"] { background: var(--apl-plan-ink); color: var(--apl-plan-bg); }
  & [aria-pressed="true"] span { color: color-mix(in oklch, var(--apl-plan-bg) 65%, transparent); }
}
.apl-plan .apl-plan-tasks {
  min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apl-plan-line2) transparent;
  display: grid; align-content: start; gap: 3px; margin: 0 -6px; padding: 2px 6px 8px;
}
.apl-plan .apl-plan-task {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 2px 10px; align-items: center; padding: 9px 8px 9px 10px; border-radius: 11px;
  background: var(--apl-plan-surface); box-shadow: 0 0 0 1px var(--apl-plan-line); cursor: grab; touch-action: pan-y; user-select: none; -webkit-user-select: none;
  transition: box-shadow .2s, opacity .25s, background .2s;
  animation: apl-plan-in .4s var(--apl-plan-ease) both; animation-delay: calc(var(--i, 0) * 28ms);
  &:hover { box-shadow: 0 0 0 1px var(--apl-plan-line2), 0 4px 12px -8px color-mix(in oklch, var(--apl-plan-ink) 40%, transparent); }
  &::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c); }
  & input { margin: 0; width: 17px; height: 17px; accent-color: var(--c); cursor: pointer; }
  & .tt { font-weight: 600; font-size: 13px; line-height: 1.3; text-wrap: pretty; min-width: 0; }
  & .mt { grid-column: 2; display: flex; gap: 8px; align-items: center; font-size: 11.5px; color: var(--apl-plan-mute); }
  & .mt i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
  & .mt .p1 { color: oklch(0.55 0.16 30); font-weight: 700; }
  & .est { font: 600 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apl-plan-mute); }
  & .go {
    grid-row: 1 / span 2; grid-column: 3; display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 8px; border: 0; border-radius: 8px;
    background: var(--apl-plan-wash); font: 600 11px ui-monospace, Menlo, monospace; color: var(--apl-plan-mute); font-variant-numeric: tabular-nums;
    & svg { width: 13px; height: 13px; }
    &:hover { background: color-mix(in oklab, var(--apl-plan-accent) 16%, var(--apl-plan-surface)); color: var(--apl-plan-ink); }
  }
  &.is-sched { background: color-mix(in oklab, var(--c) 7%, var(--apl-plan-surface)); }
  &.is-sched .go { background: color-mix(in oklab, var(--c) 18%, var(--apl-plan-surface)); color: color-mix(in oklab, var(--c) 50%, var(--apl-plan-ink)); }
  &:has(input:checked) { opacity: .55; }
  &:has(input:checked) .tt { text-decoration: line-through; text-decoration-color: var(--apl-plan-faint); }
  &.is-lift { opacity: .3; }
}
.apl-plan .apl-plan-empty { padding: 28px 10px; text-align: center; color: var(--apl-plan-mute); font-size: 12.5px; text-wrap: balance; }
.apl-plan .apl-plan-hint { font-size: 11px; color: var(--apl-plan-faint); line-height: 1.8; text-wrap: pretty; }
.apl-plan.is-drop-inbox .apl-plan-tasks { background: color-mix(in oklab, var(--apl-plan-accent) 8%, transparent); border-radius: 12px; box-shadow: inset 0 0 0 1.5px color-mix(in oklab, var(--apl-plan-accent) 45%, transparent); }

/* ── day timeline ── */
.apl-plan .apl-plan-day { grid-area: day; min-height: 0; position: relative; }
.apl-plan .apl-plan-scroll { height: 100%; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apl-plan-line2) transparent; }
.apl-plan .apl-plan-track { position: relative; display: grid; grid-template-columns: 58px minmax(0, 1fr); height: calc(13 * var(--apl-plan-hh) + 24px); padding: 12px 0; }
.apl-plan .apl-plan-hours {
  position: relative;
  & span { position: absolute; right: 10px; top: calc(var(--h) * var(--apl-plan-hh)); translate: 0 -50%; font: 500 10.5px ui-monospace, Menlo, monospace; color: var(--apl-plan-faint); font-variant-numeric: tabular-nums; }
}
.apl-plan .apl-plan-lane {
  position: relative; margin-right: 16px; border-left: 1px solid var(--apl-plan-line);
  background:
    linear-gradient(to bottom, var(--apl-plan-wash) calc(2 * var(--apl-plan-hh)), transparent 0 calc(11 * var(--apl-plan-hh)), var(--apl-plan-wash) 0),
    repeating-linear-gradient(to bottom, var(--apl-plan-line) 0 1px, transparent 1px var(--apl-plan-hh));
}
.apl-plan .apl-plan-it {
  position: absolute; z-index: 1; top: calc(var(--t) * var(--apl-plan-hh) / 60 + 1px); height: calc(var(--d) * var(--apl-plan-hh) / 60 - 2px);
  left: calc(var(--x) * 100% + 4px); width: calc(var(--w) * 100% - 6px);
  display: flex; gap: 8px; padding: 5px 9px; border-radius: 9px; overflow: hidden; min-height: 14px;
  font-size: 12px; line-height: 1.3; user-select: none; -webkit-user-select: none;
  transition: background .2s, box-shadow .25s, opacity .25s, scale .3s var(--apl-plan-spring);
  & .tx { display: grid; align-content: start; gap: 1px; min-width: 0; flex: 1; }
  & b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font: 500 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; opacity: .78; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.is-tiny { padding-block: 0; align-items: center; & .tx { grid-auto-flow: column; justify-content: start; gap: 8px; align-items: baseline; } }
}
.apl-plan .apl-plan-it.is-meet {
  color: color-mix(in oklch, var(--apl-plan-ink) 78%, var(--apl-plan-bg));
