  border-radius: 9px; border: 2px dashed var(--c); background: color-mix(in oklab, var(--c) 12%, transparent); pointer-events: none;
  padding: 4px 9px; font: 700 11px ui-monospace, Menlo, monospace; color: color-mix(in oklab, var(--c) 60%, var(--apl-plan-ink)); font-variant-numeric: tabular-nums;
  transition: top .18s var(--apl-plan-ease);
  &.is-bad { border-color: oklch(0.6 0.18 28); background: color-mix(in oklab, oklch(0.6 0.18 28) 10%, transparent); color: oklch(0.5 0.16 28); }
