  & .tr { grid-column: 1 / -1; height: 5px; border-radius: 3px; background: var(--apl-plan-line); overflow: hidden; }
  & .tr i { display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--c); border-radius: 3px; transition: width .7s var(--apl-plan-ease); }
