  & button { flex: none; border: 0; border-radius: 8px; padding: 5px 10px; font-weight: 700; background: color-mix(in oklch, var(--apl-plan-bg) 15%, transparent); color: color-mix(in oklab, var(--apl-plan-accent) 45%, white); }
