  .apl-plan[data-tab="tasks"] .apl-plan-inbox { display: grid; }
  .apl-plan[data-tab="day"] .apl-plan-day { display: block; }
  .apl-plan[data-tab="sum"] .apl-plan-sum { display: flex; padding: 16px; gap: 18px; }
  .apl-plan[data-tab="sum"] .apl-plan-sum .apl-plan-proj, .apl-plan[data-tab="sum"] .apl-plan-done, .apl-plan[data-tab="sum"] .apl-plan-sum > section { display: block; }
  .apl-plan .apl-plan-inbox, .apl-plan .apl-plan-day, .apl-plan .apl-plan-sum { animation: apl-plan-in .35s var(--apl-plan-ease); }
}
