/* ── Tidepool · day planner ──────────────────────────────────────────
   Tasks (with estimates) and fixed meetings share one minute axis. Blocks are
   tasks with a start time; placement is magnetic, so a block always lands in
   the nearest gap that fits and never double-books the day. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const EASE = 'cubic-bezier(.22,.9,.25,1)';
const SPRING = 'linear(0, 0.1 4%, 0.36 9%, 0.7 15%, 0.94 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const p2 = n => String(n).padStart(2, '0');
const hm = m => p2(Math.floor(m / 60)) + ':' + p2(m % 60);
const dur = m => { const h = Math.floor(m / 60), r = m % 60; return ((h ? h + 'h' : '') + (h && r ? ' ' : '') + (r ? r + 'm' : '')) || '0m'; };
const tm = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };

const START = 420, END = 1200, WD0 = 540, WD1 = 1080, WDLEN = WD1 - WD0;
const PROJ = {
  atlas: { name: 'Atlas redesign', c: 'var(--apl-plan-accent)' },
  hire: { name: 'Hiring', c: 'oklch(0.64 0.13 45)' },
  ops: { name: 'Design ops', c: 'oklch(0.55 0.07 250)' },
  life: { name: 'Personal', c: 'oklch(0.7 0.12 85)' },
};
const M = [
  ['09:00', '09:15', 'Atlas standup', 'Atlas squad'],
  ['10:30', '11:30', 'Design crit: checkout flow', 'Femi, Ana, Joel'],
  ['11:00', '11:45', '1:1 with Femi Adeyemi', 'Femi'],
  ['13:00', '13:45', 'Lunch with Ana', 'Ana Lisboa'],
  ['15:00', '15:30', 'Interview debrief: Kiri Hale', 'Hiring panel'],
  ['16:30', '17:30', 'Atlas × Engineering sync', '9 people'],
].map((m, i) => ({ id: 'mt' + i, s: tm(m[0]), e: tm(m[1]), title: m[2], who: m[3] }));
let seq = 0;
const task = (title, est, proj, pri, at, d, done) => ({ id: 't' + (++seq), title, est, proj, pri, at: at ? tm(at) : null, dur: d || est, done: !!done });
let T = [
  task('Review Atlas onboarding prototype', 60, 'atlas', 1, '09:15'),
  task('Write feedback on Kiri Hale’s portfolio', 30, 'hire', 1, '14:30'),
  task('Draft Q4 design-ops roadmap', 90, 'ops', 1),
  task('Update dark-mode tokens in the component kit', 45, 'atlas', 2),
  task('Expense report — Berlin offsite', 15, 'ops', 3),
  task('Prep crit deck: checkout flow', 45, 'atlas', 1, null, null, true),
  task('Book physio appointment', 15, 'life', 3),
  task('Reply to Ferrow Labs partnership email', 15, 'ops', 2, null, null, true),
  task('Sketch empty states for search', 60, 'atlas', 3),
  task('1:1 notes for Femi', 15, 'ops', 2, '10:15'),
];

const S = { filter: 'all', tab: 'day' };
const past = [], future = [];
const snapshot = () => structuredClone(T);
const find = id => T.find(t => t.id === id);
const lane = $('[data-lane]'), scroller = $('[data-scroll]'), listEl = $('[data-tasks]'), layer = $('[data-layer]'), toastEl = $('[data-toast]');
const hh = () => parseFloat(getComputedStyle(root).getPropertyValue('--apl-plan-hh')) || 60;
const ICON = {
  cal: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="9" r="3.2"/><path d="M3.5 19c.6-3.2 2.8-5 5.5-5s4.9 1.8 5.5 5"/><circle cx="16.5" cy="8" r="2.6"/><path d="M15.5 13.2c2.6-.3 4.6 1.3 5 4.3"/></svg>',
  plan: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>',
};
$('[data-hours]').innerHTML = Array.from({ length: 14 }, (_, i) => '<span style="--h:' + i + '">' + p2(7 + i) + ':00</span>').join('');

/* ── time arithmetic ── */
const busyFor = ex => M.map(m => [m.s, m.e]).concat(T.filter(t => t.at != null && t.id !== ex).map(t => [t.at, t.at + t.dur]));
const isFree = (s, d, B) => s >= START && s + d <= END && !B.some(([a, b]) => s < b && s + d > a);
function fit(s, d, ex) {
  const B = busyFor(ex);
  s = Math.round(s / 15) * 15;
  for (let k = 0; k <= 52; k++) for (const c of k ? [s + k * 15, s - k * 15] : [s]) if (isFree(c, d, B)) return c;
  return null;
}
function firstFree(d, ex, from) { const B = busyFor(ex); for (let s = from || WD0; s + d <= WD1; s += 15) if (isFree(s, d, B)) return s; return null; }
function unionLen(iv, a, b) {
  const v = iv.map(([s, e]) => [Math.max(a, s), Math.min(b, e)]).filter(([s, e]) => e > s).sort((x, y) => x[0] - y[0]);
  let tot = 0, cs = -1, ce = -1;
  v.forEach(([s, e]) => { if (s > ce) { if (ce > cs) tot += ce - cs; cs = s; ce = e; } else ce = Math.max(ce, e); });
  if (ce > cs) tot += ce - cs;
  return tot;
}
function gaps() {
  const B = busyFor(null).sort((a, b) => a[0] - b[0]), out = [];
  let c = WD0;
  B.forEach(([s, e]) => { if (s > c && c < WD1) out.push([c, Math.min(s, WD1)]); c = Math.max(c, e); });
  if (c < WD1) out.push([c, WD1]);
  return out.filter(([s, e]) => e - s >= 15);
}

/* ── overlap layout (meetings can collide; blocks never do) ── */
function layout(list) {
  const out = new Map();
  let cluster = [], colz = [], end = -1;
  const flush = () => {
    const n = colz.length;
    cluster.forEach(o => {
      let span = 1;
      for (let c = o.col + 1; c < n; c++) { if (colz[c].some(x => x.s < o.e && x.e > o.s)) break; span++; }
      out.set(o.id, { x: o.col / n, w: span / n });
    });
    cluster = []; colz = [];
  };
  list.sort((a, b) => a.s - b.s || b.e - a.e).forEach(it => {
    if (it.s >= end && cluster.length) flush();
    let c = colz.findIndex(col => col[col.length - 1].e <= it.s);
    if (c < 0) { c = colz.length; colz.push([]); }
    colz[c].push(it); it.col = c; cluster.push(it); end = Math.max(end, it.e);
  });
  if (cluster.length) flush();
  return out;
}

/* ── render ── */
const blockEls = new Map();
function renderDay() {
  const items = M.map(m => ({ id: m.id, s: m.s, e: m.e, meet: m })).concat(T.filter(t => t.at != null).map(t => ({ id: t.id, s: t.at, e: t.at + t.dur, task: t })));
  const L = layout(items);
  const keep = new Set();
  items.forEach(it => {
    let el = blockEls.get(it.id);
    if (!el) { el = doc.createElement('div'); el.dataset.id = it.id; blockEls.set(it.id, el); el._h = ''; }
    const l = L.get(it.id), d = it.e - it.s, tiny = d <= 30;
    let h, cls;
    if (it.meet) {
      cls = 'apl-plan-it is-meet' + (tiny ? ' is-tiny' : '');
      h = ICON.cal + '<span class="tx"><b>' + esc(it.meet.title) + '</b><small>' + hm(it.s) + '–' + hm(it.e) + (tiny ? '' : ' · ' + esc(it.meet.who)) + '</small></span>';
      el.setAttribute('aria-label', it.meet.title + ', meeting, ' + hm(it.s) + ' to ' + hm(it.e));
    } else {
      const t = it.task, p = PROJ[t.proj];
      cls = 'apl-plan-it is-block' + (tiny ? ' is-tiny' : '');
      h = '<input type="checkbox" data-done="' + t.id + '" aria-label="Done"' + (t.done ? ' checked' : '') + '><span class="tx"><b>' + esc(t.title) + '</b><small>' + hm(it.s) + '–' + hm(it.e) + (tiny ? '' : ' · ' + p.name) + '</small></span><i class="rz" aria-hidden="true"></i>';
      el.tabIndex = 0; el.setAttribute('role', 'button');
      el.setAttribute('aria-label', t.title + ', ' + hm(it.s) + ' to ' + hm(it.e) + (t.done ? ', done' : '') + '. Arrow keys move, Shift resizes, Backspace unschedules.');
      el.style.setProperty('--c', p.c);
    }
    const keepCls = el.classList.contains('is-flash') ? ' is-flash' : '';
    if (el.className !== cls + keepCls) el.className = cls + keepCls;
    if (el._h !== h) { el.innerHTML = h; el._h = h; }
    el.style.setProperty('--t', it.s - START); el.style.setProperty('--d', d);
    el.style.setProperty('--x', l.x); el.style.setProperty('--w', l.w);
    if (el.parentNode !== lane) lane.append(el);
    keep.add(it.id);
  });
  blockEls.forEach((el, id) => { if (!keep.has(id)) { el.remove(); blockEls.delete(id); } });
  /* free gaps worth filling */
  $$('.apl-plan-free', lane).forEach(n => n.remove());
  gaps().filter(([s, e]) => e - s >= 30).forEach(([s, e]) => {
    const b = doc.createElement('button');
    b.type = 'button'; b.className = 'apl-plan-free'; b.dataset.fill = s + ':' + e;
    b.style.setProperty('--t', s - START); b.style.setProperty('--d', e - s);
    b.innerHTML = '<span>' + dur(e - s) + ' free</span><em>· Fill</em>';
    b.setAttribute('aria-label', dur(e - s) + ' free from ' + hm(s) + '. Fill with a task.');
    lane.prepend(b);
  });
}

function renderList() {
