    if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); const rs = $$('.apl-plan-task', listEl), i = rs.indexOf(row), n = rs[clamp(i + (k === 'ArrowDown' ? 1 : -1), 0, rs.length - 1)]; n.focus(); n.scrollIntoView({ block: 'nearest' }); return; }
    if (k === 'Enter') { e.preventDefault(); if (t.at == null) plan(id); else { if (narrow()) setTab('day'); reveal(id); flash(id); } return; }
    if (k === ' ') { e.preventDefault(); toggleDone(id); return; }
    if (k === 'Backspace' || k === 'Delete') {
      e.preventDefault();
      if (t.at != null) unplan(id);
      else { const snap = snapshot(); T = T.filter(x => x !== t); render(); commit(snap, 'Deleted “' + t.title + '”'); }
      return;
    }
  }
  if (blk) {
    const id = blk.dataset.id, t = find(id);
    if (k === 'ArrowUp' || k === 'ArrowDown') {
      e.preventDefault();
      const snap = snapshot(), dm = k === 'ArrowUp' ? -15 : 15;
      if (e.shiftKey) {
        const nd = t.dur + dm, B = busyFor(id);
        if (nd < 15 || !isFree(t.at, nd, B)) return;
        t.dur = nd;
      } else {
        const B = busyFor(id); let s = t.at + dm;
        while (s >= START && s + t.dur <= END && !isFree(s, t.dur, B)) s += dm;
        if (s < START || s + t.dur > END) return;
        t.at = s;
      }
      flipBlocks(() => { renderDay(); renderSum(); }); renderList();
      blockEls.get(id).focus({ preventScroll: true }); reveal(id);
      commit(snap, '“' + t.title + '” ' + hm(t.at) + '–' + hm(t.at + t.dur), 'nudge:' + id);
      return;
    }
    if (k === 'Backspace' || k === 'Delete') { e.preventDefault(); unplan(id); root.focus({ preventScroll: true }); return; }
    if (k === ' ' || k.toLowerCase() === 'x') { e.preventDefault(); toggleDone(id); const el = blockEls.get(id); if (el) el.focus({ preventScroll: true }); return; }
  }
  const key = k.length === 1 ? k.toLowerCase() : k;
  if (key === 'a') { e.preventDefault(); autoSchedule(); }
  else if (key === '/' || key === 'n') { e.preventDefault(); if (narrow()) setTab('tasks'); $('[data-addi]').focus(); }
});
root.addEventListener('pointerdown', e => { if (!e.target.closest('button, input, .apl-plan-task, .apl-plan-it, label')) root.focus({ preventScroll: true }); });

render();
scroller.scrollTop = (WD0 - START - 30) / 60 * hh();

css:
.apl-find {
  /* theme */
  --apl-find-bg: oklch(0.985 0.003 240);
  --apl-find-ink: oklch(0.23 0.025 255);
  --apl-find-accent: oklch(0.5 0.1 205);
  --apl-find-surface: oklch(1 0 none);
  --apl-find-ok: oklch(0.63 0.14 155);
  --apl-find-warn: oklch(0.74 0.15 70);
  --apl-find-bad: oklch(0.6 0.19 25);
  --apl-find-line: color-mix(in oklch, var(--apl-find-ink) 9%, transparent);
  --apl-find-line2: color-mix(in oklch, var(--apl-find-ink) 17%, transparent);
  --apl-find-mute: color-mix(in oklch, var(--apl-find-ink) 56%, var(--apl-find-bg));
  --apl-find-faint: color-mix(in oklch, var(--apl-find-ink) 34%, var(--apl-find-bg));
  --apl-find-day: color-mix(in oklab, var(--apl-find-ok) 9%, var(--apl-find-surface));
  --apl-find-eve: color-mix(in oklch, var(--apl-find-ink) 4%, var(--apl-find-bg));
  --apl-find-night: color-mix(in oklch, var(--apl-find-ink) 10%, var(--apl-find-bg));
  --apl-find-ease: cubic-bezier(.2, .85, .25, 1);
  --apl-find-spring: linear(0, 0.1 4%, 0.37 9%, 0.72 15%, 0.95 22%, 1.05 28%, 1.06 33%, 1.03 40%, 1.005 52%, 1);
  --apl-find-nw: 236px; --apl-find-hw: 58px;

  position: relative; width: 100%; height: var(--apl-find-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-find-bg); color: var(--apl-find-ink); color-scheme: light; accent-color: var(--apl-find-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 14px;
  box-shadow: 0 0 0 1px var(--apl-find-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-find-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h3, & p, & ol, & ul, & dl { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; display: inline-block; text-align: center;
    border: 1px solid var(--apl-find-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-find-mute); background: var(--apl-find-surface);
  }
}
.apl-find .apl-find-app {
  height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head" "grid sugg";
}

/* ── header ── */
.apl-find .apl-find-head {
  grid-area: head; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "ttl ctl";
  gap: 12px 20px; align-items: center; padding: 16px 18px 14px 20px; border-bottom: 1px solid var(--apl-find-line);
}
.apl-find .apl-find-ttl {
  grid-area: ttl; min-width: 0;
  & input { width: 100%; border: 0; outline: 0; background: none; padding: 0; font-size: clamp(18px, 1.4cqi + 6px, 24px); font-weight: 740; letter-spacing: -.025em; text-overflow: ellipsis; }
  & input:focus { box-shadow: 0 2px 0 var(--apl-find-accent); }
  & p { margin-top: 4px; font-size: 12.5px; color: var(--apl-find-mute); font-variant-numeric: tabular-nums; display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: center; }
  & p b { color: var(--apl-find-ink); font-weight: 650; }
  & p .st { display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 2px 6px; border-radius: 20px; font-weight: 650; font-size: 11.5px; background: color-mix(in oklab, var(--st) 14%, var(--apl-find-surface)); color: color-mix(in oklab, var(--st) 60%, var(--apl-find-ink)); transition: background .3s, color .3s; }
  & p .st i { width: 7px; height: 7px; border-radius: 50%; background: var(--st); }
}
.apl-find .apl-find-ctl { grid-area: ctl; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.apl-find .apl-find-ib {
  display: grid; place-items: center; width: 28px; height: 28px; border: 0; border-radius: 8px; background: none; color: var(--apl-find-mute);
  &:hover { background: var(--apl-find-line); color: var(--apl-find-ink); }
}
.apl-find .apl-find-day {
  display: flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: var(--apl-find-surface); box-shadow: 0 0 0 1px var(--apl-find-line2);
  & b { min-width: 86px; text-align: center; font-weight: 650; font-size: 12.5px; font-variant-numeric: tabular-nums; }
}
.apl-find .apl-find-dur {
  display: flex; padding: 2px; border-radius: 10px; background: var(--apl-find-line); gap: 2px;
  & button { border: 0; background: none; padding: 5px 9px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--apl-find-mute); font-variant-numeric: tabular-nums; transition: background .2s, color .2s; }
  & [aria-checked="true"] { background: var(--apl-find-surface); color: var(--apl-find-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--apl-find-ink) 16%, transparent); }
}
.apl-find .apl-find-zone {
  display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 8px 0 10px; border-radius: 10px; background: var(--apl-find-surface); box-shadow: 0 0 0 1px var(--apl-find-line2); color: var(--apl-find-mute);
  & select { border: 0; outline: 0; background: none; font-size: 12.5px; font-weight: 600; color: var(--apl-find-ink); cursor: pointer; }
}
.apl-find .apl-find-send {
  display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 9px 0 13px; border: 0; border-radius: 10px; font-weight: 700; font-size: 12.5px;
  background: var(--apl-find-ink); color: var(--apl-find-bg); transition: scale .3s var(--apl-find-spring), background .2s;
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--apl-find-bg) 35%, transparent); }
  &:hover { background: color-mix(in oklch, var(--apl-find-ink) 85%, var(--apl-find-accent)); }
  &:active { scale: .97; }
  &.is-sent { background: var(--apl-find-ok); }
}
.apl-find .apl-find-tabs {
  grid-area: tabs; display: none; padding: 3px; gap: 2px; border-radius: 10px; background: var(--apl-find-line);
  & button { flex: 1; border: 0; background: none; padding: 6px; border-radius: 8px; font-weight: 650; font-size: 12.5px; color: var(--apl-find-mute); }
  & [aria-selected="true"] { background: var(--apl-find-surface); color: var(--apl-find-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--apl-find-ink) 15%, transparent); }
}

/* ── availability grid ── */
.apl-find .apl-find-grid { grid-area: grid; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; }
.apl-find .apl-find-scroll { min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--apl-find-line2) transparent; }
.apl-find .apl-find-sheet { position: relative; width: calc(var(--apl-find-nw) + 24 * var(--apl-find-hw)); min-height: 100%; }
.apl-find .apl-find-ruler {
  position: sticky; top: 0; z-index: 6; display: grid; grid-template-columns: var(--apl-find-nw) repeat(24, var(--apl-find-hw)); height: 34px;
  background: color-mix(in oklch, var(--apl-find-bg) 94%, transparent); backdrop-filter: blur(6px); border-bottom: 1px solid var(--apl-find-line2);
  & .cn { position: sticky; left: 0; z-index: 2; display: flex; align-items: center; padding: 0 14px 0 20px; background: var(--apl-find-bg); font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--apl-find-mute); border-right: 1px solid var(--apl-find-line2); }
  & span { align-self: end; padding: 0 0 7px 5px; font: 500 10.5px ui-monospace, Menlo, monospace; color: var(--apl-find-faint); font-variant-numeric: tabular-nums; border-left: 1px solid var(--apl-find-line); }
  & span.is-wd { color: var(--apl-find-ink); font-weight: 650; }
}
.apl-find .apl-find-row {
  display: grid; grid-template-columns: var(--apl-find-nw) calc(24 * var(--apl-find-hw)); height: 62px; border-bottom: 1px solid var(--apl-find-line);
  animation: apl-find-in .45s var(--apl-find-ease) both; animation-delay: calc(var(--i, 0) * 40ms);
  &.is-out { animation: apl-find-out .3s ease-in forwards; }
}
.apl-find .apl-find-allrow {
  height: 46px; border-bottom: 1px solid var(--apl-find-line2); animation: none;
  & .apl-find-who { background: color-mix(in oklch, var(--apl-find-ink) 2.5%, var(--apl-find-bg)); }
  & .av.all { background: var(--apl-find-ink); --st: transparent; }
  & .av.all::after { display: none; }
  & .av svg { width: 15px; height: 15px; color: var(--apl-find-bg); }
  & .apl-find-trk { background: color-mix(in oklch, var(--apl-find-ink) 2.5%, var(--apl-find-bg)) repeating-linear-gradient(to right, var(--apl-find-line) 0 1px, transparent 1px var(--apl-find-hw)); }
  & .seg { top: 13px; bottom: 13px; border-radius: 4px; }
  & .seg.all { background: var(--apl-find-ok); }
  & .seg.part { background: repeating-linear-gradient(90deg, color-mix(in oklab, var(--apl-find-warn) 70%, var(--apl-find-surface)) 0 4px, color-mix(in oklab, var(--apl-find-warn) 35%, var(--apl-find-surface)) 4px 8px); }
}
.apl-find .apl-find-who {
  position: sticky; left: 0; z-index: 4; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 0 10px; align-items: center; padding: 0 8px 0 20px;
  background: var(--apl-find-bg); border-right: 1px solid var(--apl-find-line2);
  & .av { position: relative; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font-size: 11px; font-weight: 750; color: oklch(0.99 0 0); background: oklch(0.58 0.09 calc(var(--h) * 1deg)); }
  & .av::after { content: ""; position: absolute; right: -2px; bottom: -2px; width: 11px; height: 11px; border-radius: 50%; border: 2px solid var(--apl-find-bg); background: var(--st); transition: background .25s; }
  & .nm { min-width: 0; display: grid; }
  & .nm b { font-weight: 650; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { font-size: 11px; color: var(--apl-find-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .nm small em { font-style: normal; color: color-mix(in oklab, var(--st) 70%, var(--apl-find-ink)); font-weight: 600; }
  & .rq { border: 0; padding: 2px 6px; border-radius: 6px; background: none; font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--apl-find-faint); }
  & .rq:hover { background: var(--apl-find-line); color: var(--apl-find-ink); }
  & .rq[aria-pressed="true"] { color: var(--apl-find-accent); }
  & .rm { position: absolute; left: 2px; top: 50%; translate: 0 -50%; width: 16px; height: 16px; border: 0; border-radius: 50%; padding: 0; display: grid; place-items: center; background: none; color: var(--apl-find-faint); opacity: 0; transition: opacity .15s; }
  & .rm svg { width: 11px; height: 11px; stroke-width: 2.4; }
  & .rm:hover { color: var(--apl-find-bad); }
}
.apl-find .apl-find-row:hover .apl-find-who .rm, .apl-find .apl-find-who .rm:focus-visible { opacity: 1; }
.apl-find .apl-find-trk {
  position: relative; overflow: hidden;
  background: var(--apl-find-night) repeating-linear-gradient(to right, var(--apl-find-line) 0 1px, transparent 1px var(--apl-find-hw));
  & .seg { position: absolute; top: 0; bottom: 0; left: calc(var(--s) / 60 * var(--apl-find-hw)); width: calc(var(--d) / 60 * var(--apl-find-hw)); }
  & .seg.eve { background: var(--apl-find-eve); }
  & .seg.wh { background: var(--apl-find-day); box-shadow: inset 0 2px 0 color-mix(in oklab, var(--apl-find-ok) 45%, transparent); }
  & .bz {
    position: absolute; top: 9px; bottom: 9px; left: calc(var(--s) / 60 * var(--apl-find-hw) + 1px); width: calc(var(--d) / 60 * var(--apl-find-hw) - 2px);
    border-radius: 6px; padding: 4px 6px; overflow: hidden; font-size: 10.5px; font-weight: 600; white-space: nowrap; text-overflow: ellipsis; line-height: 1.6;
    background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--apl-find-ink) 22%, var(--apl-find-surface)) 0 5px, color-mix(in oklch, var(--apl-find-ink) 15%, var(--apl-find-surface)) 5px 10px);
    color: color-mix(in oklch, var(--apl-find-ink) 82%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apl-find-ink) 14%, transparent);
  }
  & .bz.is-hit { background: repeating-linear-gradient(-45deg, color-mix(in oklab, var(--apl-find-bad) 34%, var(--apl-find-surface)) 0 5px, color-mix(in oklab, var(--apl-find-bad) 22%, var(--apl-find-surface)) 5px 10px); color: color-mix(in oklab, var(--apl-find-bad) 55%, var(--apl-find-ink)); box-shadow: inset 0 0 0 1.5px var(--apl-find-bad); }
  & .nt { position: absolute; top: 50%; translate: 0 -50%; left: calc(var(--s) / 60 * var(--apl-find-hw) + 6px); font: 500 10px ui-monospace, Menlo, monospace; color: var(--apl-find-faint); pointer-events: none; display: flex; align-items: center; gap: 4px; }
  & .nt svg { width: 11px; height: 11px; }
}
.apl-find .apl-find-win {
  --st: var(--apl-find-ok);
  position: absolute; z-index: 5; top: 34px; bottom: 0; left: var(--apl-find-nw); width: calc(var(--d) / 60 * var(--apl-find-hw)); translate: calc(var(--s) / 60 * var(--apl-find-hw)) 0;
  border-radius: 8px; border: 2px solid var(--st); background: color-mix(in oklab, var(--st) 10%, transparent); cursor: grab; touch-action: none;
  box-shadow: 0 0 0 4px color-mix(in oklab, var(--st) 14%, transparent), 0 10px 30px -14px color-mix(in oklab, var(--st) 70%, transparent);
  transition: translate .55s var(--apl-find-spring), border-color .3s, background .3s, box-shadow .3s;
  &.is-drag { transition: border-color .3s, background .3s; cursor: grabbing; }
  &.is-warn { --st: var(--apl-find-warn); }
  &.is-bad { --st: var(--apl-find-bad); }
  &:focus-visible { outline: 2px solid var(--apl-find-ink); outline-offset: 3px; }
}
.apl-find .apl-find-wlab {
  position: absolute; z-index: 3; top: 5px; left: var(--apl-find-nw); width: calc(var(--d) / 60 * var(--apl-find-hw)); translate: calc(var(--s) / 60 * var(--apl-find-hw)) 0;
  display: flex; justify-content: center; pointer-events: none;
  transition: translate .55s var(--apl-find-spring);
  & b { white-space: nowrap; padding: 3px 8px; border-radius: 7px; font: 700 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; background: var(--st); color: oklch(0.99 0 0); transition: background .3s; box-shadow: 0 4px 10px -4px color-mix(in oklab, var(--st) 80%, transparent); }
  &.is-drag { transition: none; }
}
.apl-find .apl-find-wrz { position: absolute; right: -6px; top: 0; bottom: 0; width: 12px; cursor: ew-resize; }
.apl-find .apl-find-wrz::after { content: ""; position: absolute; left: 4px; top: 50%; width: 4px; height: 26px; translate: 0 -50%; border-radius: 2px; background: var(--st); }

.apl-find .apl-find-add {
  position: relative; display: flex; align-items: center; gap: 9px; padding: 10px 16px 12px 20px; border-top: 1px solid var(--apl-find-line);
  & > svg { color: var(--apl-find-accent); }
  & input { flex: 1; min-width: 0; height: 32px; border: 0; outline: 0; background: none; font-size: 13px; }
  & input::placeholder { color: var(--apl-find-faint); }
}
.apl-find .apl-find-dir {
  position: absolute; left: 14px; bottom: calc(100% - 4px); z-index: 20; width: min(340px, calc(100% - 28px)); display: none; padding: 6px; border-radius: 12px;
  background: var(--apl-find-surface); box-shadow: 0 0 0 1px var(--apl-find-line2), 0 -18px 40px -18px color-mix(in oklch, var(--apl-find-ink) 45%, transparent);
  &.is-on { display: block; }
  @starting-style { &.is-on { opacity: 0; translate: 0 6px; } }
  transition: opacity .18s, translate .3s var(--apl-find-ease);
  & li { display: grid; grid-template-columns: auto 1fr auto; gap: 0 10px; align-items: center; padding: 7px 8px; border-radius: 8px; cursor: pointer; }
  & li[aria-selected="true"] { background: color-mix(in oklab, var(--apl-find-accent) 10%, var(--apl-find-surface)); }
  & .av { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; font-size: 10px; font-weight: 750; color: oklch(0.99 0 0); background: oklch(0.58 0.09 calc(var(--h) * 1deg)); }
  & .av.room { border-radius: 7px; background: var(--apl-find-accent); }
  & b { font-size: 12.5px; font-weight: 650; display: block; }
  & small { font-size: 11px; color: var(--apl-find-mute); }
  & time { font: 500 11px ui-monospace, Menlo, monospace; color: var(--apl-find-mute); }
  & .none { display: block; padding: 10px; color: var(--apl-find-mute); font-size: 12px; cursor: default; }
}

/* ── suggestions ── */
.apl-find .apl-find-sugg {
  grid-area: sugg; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; gap: 12px; padding: 16px 16px 14px;
  border-left: 1px solid var(--apl-find-line); background: color-mix(in oklch, var(--apl-find-ink) 2.5%, var(--apl-find-bg));
  & header { display: flex; align-items: center; justify-content: space-between; }
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .13em; text-transform: uppercase; color: var(--apl-find-mute); }
  & ol { min-height: 0; overflow-y: auto; scrollbar-width: none; display: grid; align-content: start; gap: 8px; }
}
.apl-find .apl-find-opt { display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--apl-find-mute); cursor: pointer; & input { margin: 0; } }
.apl-find .apl-find-sg {
  width: 100%; display: grid; grid-template-columns: auto 1fr; gap: 6px 10px; padding: 11px 12px; border: 0; border-radius: 12px; text-align: left;
  background: var(--apl-find-surface); box-shadow: 0 0 0 1px var(--apl-find-line);
  animation: apl-find-in .45s var(--apl-find-ease) both; animation-delay: calc(var(--i) * 55ms);
  transition: box-shadow .2s, translate .3s var(--apl-find-spring);
