  sao: { name: 'São Paulo', abbr: 'BRT', off: -180 }, sfo: { name: 'San Francisco', abbr: 'PDT', off: -420 }, tyo: { name: 'Tokyo', abbr: 'JST', off: 540 },
  dxb: { name: 'Dubai', abbr: 'GST', off: 240 }, los: { name: 'Lagos', abbr: 'WAT', off: 60 }, osl: { name: 'Oslo', abbr: 'CEST', off: 120 },
