const DIR = [
  { id: 'ml', name: 'Mara Lindqvist', role: 'Head of Product', z: 'lon', wh: [540, 1050] },
  { id: 'dr', name: 'Dev Raman', role: 'Eng lead, Payments', z: 'blr', wh: [570, 1110] },
  { id: 'sa', name: 'Sofia Alvarez', role: 'Design director', z: 'nyc', wh: [540, 1020] },
  { id: 'tf', name: 'Tomás Ferreira', role: 'Data science', z: 'sao', wh: [540, 1080] },
  { id: 'ab', name: 'Aiyana Brooks', role: 'PM, Growth', z: 'sfo', wh: [510, 990] },
  { id: 'km', name: 'Kenji Mori', role: 'Partnerships, APAC', z: 'tyo', wh: [600, 1140] },
