@property --apl-book-draw { syntax: '<number>'; inherits: true; initial-value: 0; }

.apl-book {
  /* theme */
  --apl-book-bg: oklch(0.975 0.014 85);
  --apl-book-ink: oklch(0.24 0.03 340);
  --apl-book-accent: oklch(0.52 0.17 350);
  --apl-book-surface: oklch(0.995 0.005 85);
  --apl-book-line: color-mix(in oklch, var(--apl-book-ink) 10%, transparent);
  --apl-book-line2: color-mix(in oklch, var(--apl-book-ink) 18%, transparent);
  --apl-book-mute: color-mix(in oklch, var(--apl-book-ink) 58%, var(--apl-book-bg));
  --apl-book-faint: color-mix(in oklch, var(--apl-book-ink) 32%, var(--apl-book-bg));
  --apl-book-tint: color-mix(in oklab, var(--apl-book-accent) 10%, var(--apl-book-surface));
  --apl-book-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --apl-book-ease: cubic-bezier(.2, .85, .2, 1);
  --apl-book-spring: linear(0, 0.09 4%, 0.34 9%, 0.68 15%, 0.93 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1);

  position: relative; width: 100%; height: var(--apl-book-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-book-bg); color: var(--apl-book-ink); color-scheme: light; accent-color: var(--apl-book-accent);
  font: 13.5px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 18px;
  box-shadow: 0 0 0 1px var(--apl-book-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-book-accent); outline-offset: 2px; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; display: inline-block; text-align: center; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .65; }
}
.apl-book .apl-book-app {
  height: 100%; display: grid; grid-template-columns: 300px minmax(0, 1fr) 272px; grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "host cal slots";
}
