  flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--apl-book-line2) transparent; display: grid; align-content: start; gap: 8px; padding: 2px 14px 10px 2px;
  & li { display: grid; grid-template-columns: 1fr 0fr; gap: 0; transition: grid-template-columns .4s var(--apl-book-ease), gap .4s var(--apl-book-ease); animation: apl-book-rise .4s var(--apl-book-ease) both; animation-delay: calc(var(--i) * 22ms); }
