}

@keyframes apl-book-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes apl-book-pop { from { opacity: 0; scale: .6; } }
@keyframes apl-book-draw { to { --apl-book-draw: 1; } }
@keyframes apl-book-ring { 0% { opacity: .8; scale: .8; } 100% { opacity: 0; scale: 1.5; } }
@keyframes apl-book-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }
@keyframes apl-book-slide-l { from { opacity: 0; translate: -18px 0; } }
