  .apl-book .apl-book-steps li::after { content: ""; display: block; height: 100%; background: var(--apl-book-accent); scale: var(--f, 0) 1; transform-origin: left; transition: scale .5s var(--apl-book-ease); }
  .apl-book .apl-book-steps span { font-size: 11.5px; font-weight: 650; color: var(--apl-book-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 58%; }
  .apl-book .apl-book-types { margin-top: 4px; }
