  .apl-book .apl-book-list { grid-template-columns: 1fr; }
  .apl-book .apl-book-form { padding: 16px 18px; }
  .apl-book .apl-book-go kbd { display: none; }
  .apl-book .apl-book-host, .apl-book .apl-book-cal, .apl-book .apl-book-slots { animation: apl-book-rise .35s var(--apl-book-ease); }
}

@media (prefers-reduced-motion: reduce) {
  .apl-book *, .apl-book *::before, .apl-book *::after { animation-duration: .01ms !important; animation-delay: 0s !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
