/* ── Brightwater · public booking page ───────────────────────────────
   Availability is authored in the host's wall-clock time (Lisbon). Every
   slot is turned into a UTC instant using the offset in force on that day,
   then re-projected into the visitor's zone — so the Oct 25 (EU), Nov 1 (US)
   and Oct 4 (Sydney) clock changes all land where they should. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
$$('[data-mod]').forEach(k => { k.textContent = MAC ? '⌘' : 'Ctrl'; });
const DAY = 864e5;
const D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const p2 = n => String(n).padStart(2, '0');

/* zone rules for autumn 2026, as instants in UTC minutes */
const T_EU = D(2026, 10, 25) * 1440 + 60, T_USE = D(2026, 11, 1) * 1440 + 360, T_USW = D(2026, 11, 1) * 1440 + 540, T_SYD = D(2026, 10, 3) * 1440 + 960;
const ZONES = {
  lax: { name: 'Los Angeles', off: u => u < T_USW ? -420 : -480, ab: u => u < T_USW ? 'PDT' : 'PST', ch: T_USW },
  nyc: { name: 'New York', off: u => u < T_USE ? -240 : -300, ab: u => u < T_USE ? 'EDT' : 'EST', ch: T_USE },
  sao: { name: 'São Paulo', off: () => -180, ab: () => 'BRT' },
  lon: { name: 'London', off: u => u < T_EU ? 60 : 0, ab: u => u < T_EU ? 'BST' : 'GMT', ch: T_EU },
  lis: { name: 'Lisbon', off: u => u < T_EU ? 60 : 0, ab: u => u < T_EU ? 'WEST' : 'WET', ch: T_EU },
  ber: { name: 'Berlin', off: u => u < T_EU ? 120 : 60, ab: u => u < T_EU ? 'CEST' : 'CET', ch: T_EU },
  dxb: { name: 'Dubai', off: () => 240, ab: () => 'GST' },
  sin: { name: 'Singapore', off: () => 480, ab: () => 'SGT' },
  tyo: { name: 'Tokyo', off: () => 540, ab: () => 'JST' },
  syd: { name: 'Sydney', off: u => u < T_SYD ? 600 : 660, ab: u => u < T_SYD ? 'AEST' : 'AEDT', ch: T_SYD },
};
const HOST = ZONES.lis;
const TYPES = [
  { id: 'intro', name: 'Intro call', len: 20, step: 30, where: 'Video call', blurb: 'A short first conversation: what you are building, where the brand feels stuck, and whether we are a good fit.' },
  { id: 'audit', name: 'Brand audit review', len: 45, step: 30, where: 'Video call', blurb: 'We walk through your audit deck together, page by page, and leave with three decisions written down.' },
  { id: 'work', name: 'Strategy workshop', len: 90, step: 60, where: 'Rua das Flores 28, Lisbon', blurb: 'A working session at the studio. Bring the team; we bring paper, coffee and a facilitator.' },
];
const HOLIDAYS = { [D(2026, 10, 5)]: 'Republic Day', [D(2026, 12, 1)]: 'Restoration of Independence', [D(2026, 12, 8)]: 'Immaculate Conception' };
const NOW = D(2026, 10, 2) * 1440 + 14 * 60 - 60;   /* Fri Oct 2, 14:00 in Lisbon */
const MIN_NOTICE = 24 * 60, HORIZON = D(2026, 12, 18);
const FULL = new Set([D(2026, 10, 13), D(2026, 10, 22), D(2026, 11, 10)]);

function seeded(n) { let h = n * 2654435761 >>> 0; return () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) ^ Math.imul(h ^ (h >>> 13), 3266489909)) >>> 0) / 4294967296; }
/* host's existing commitments on a given host-local day */
function taken(day) {
  if (FULL.has(day)) return [[0, 1440]];
  const r = seeded(day), out = [];
  const n = 1 + Math.floor(r() * 2);
  for (let i = 0; i < n; i++) { const s = 540 + Math.floor(r() * 14) * 30; out.push([s, s + 60]); }
  return out;
}
const booked = new Map();   /* utc start -> booking, so a booked slot disappears */
function slotsFor(type) {
  const out = [];
  for (let d = D(2026, 10, 3); d <= HORIZON; d++) {
    const w = dow(d);
    if (w === 0 || w === 6 || HOLIDAYS[d]) continue;
    const wins = w === 5 ? [[540, 780]] : [[540, 750], [810, 1020]];
    const busy = taken(d);
    wins.forEach(([a, b]) => {
      for (let s = a; s + type.len <= b; s += type.step) {
        if (busy.some(([x, y]) => s < y && s + type.len > x)) continue;
        const guess = d * 1440 + s - 60, u = d * 1440 + s - HOST.off(guess);
        if (u < NOW + MIN_NOTICE || booked.has(u)) continue;
        out.push(u);
      }
    });
  }
  return out;
}

/* ── state ── */
const S = { type: 'audit', tz: 'ber', month: null, date: null, pick: null, fmt: 12, step: 'pick', pane: 'host', guests: [], booking: null };
const past = [];
const ICON = {
  clock: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/></svg>',
  video: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="6.5" width="12.5" height="11" rx="2.5"/><path d="m15.5 10.5 5-3v9l-5-3"/></svg>',
  pin: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0 1 13 0c0 5.4-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.3"/></svg>',
  cal: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/></svg>',
  globe: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M3.5 12h17M12 3.5c2.6 2.4 3.8 5.2 3.8 8.5s-1.2 6.1-3.8 8.5c-2.6-2.4-3.8-5.2-3.8-8.5s1.2-6.1 3.8-8.5z"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>',
