css:
.apl-agenda {
  /* theme */
  --apl-agenda-bg: oklch(0.2 0.012 55);
  --apl-agenda-ink: oklch(0.94 0.015 75);
  --apl-agenda-accent: oklch(0.8 0.12 62);
  --apl-agenda-panel: oklch(0.235 0.014 55);
  --apl-agenda-line: color-mix(in oklch, var(--apl-agenda-ink) 9%, transparent);
  --apl-agenda-line2: color-mix(in oklch, var(--apl-agenda-ink) 16%, transparent);
  --apl-agenda-mute: color-mix(in oklch, var(--apl-agenda-ink) 58%, var(--apl-agenda-bg));
  --apl-agenda-faint: color-mix(in oklch, var(--apl-agenda-ink) 36%, var(--apl-agenda-bg));
  --apl-agenda-on: oklch(0.22 0.03 60);
  --apl-agenda-ease: cubic-bezier(.2, .85, .25, 1);
  --apl-agenda-spring: linear(0, 0.09 4%, 0.34 9%, 0.68 15%, 0.93 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1);

  position: relative; width: 100%; height: var(--apl-agenda-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-agenda-bg); color: var(--apl-agenda-ink); color-scheme: dark; accent-color: var(--apl-agenda-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-agenda-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & h4, & p, & ol, & ul, & dl { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & mark { background: color-mix(in oklab, var(--apl-agenda-accent) 35%, transparent); color: inherit; border-radius: 3px; padding: 0 1px; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; display: inline-block; text-align: center; border: 1px solid var(--apl-agenda-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-agenda-mute); }
}
.apl-agenda .apl-agenda-app {
  height: 100%; display: grid; grid-template-columns: 248px minmax(0, 1fr) 330px; grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "side list detail"; timeline-scope: --apl-agenda-sc;
}

/* ── side ── */
.apl-agenda .apl-agenda-side { grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 20px; padding: 20px 16px; border-right: 1px solid var(--apl-agenda-line); }
.apl-agenda .apl-agenda-me {
  display: flex; align-items: center; gap: 10px;
  & > span:last-child { display: grid; }
  & b { font-weight: 650; }
  & small { font-size: 11.5px; color: var(--apl-agenda-mute); }
}
.apl-agenda .apl-agenda-av { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; font-weight: 750; font-size: 12px; background: var(--apl-agenda-accent); color: var(--apl-agenda-on); }
.apl-agenda .apl-agenda-mini {
  & header { padding: 0 4px 8px; font-size: 13px; }
  & header b { font-weight: 700; }
  & header span { color: var(--apl-agenda-faint); }
}
.apl-agenda .apl-agenda-mgrid {
  display: grid; grid-template-columns: repeat(7, 1fr); row-gap: 2px;
  & > span { text-align: center; font-size: 9.5px; font-weight: 700; color: var(--apl-agenda-faint); padding-bottom: 4px; }
  & button {
    position: relative; aspect-ratio: 1; display: grid; place-items: center; border: 0; background: none; border-radius: 8px; font-size: 11.5px; font-variant-numeric: tabular-nums; color: var(--apl-agenda-faint);
    transition: background .25s, color .25s;
    &.has { color: var(--apl-agenda-ink); }
    &.has::after { content: ""; position: absolute; bottom: 3px; width: 3px; height: 3px; border-radius: 50%; background: var(--apl-agenda-mute); }
    &.has.inv::after { background: var(--apl-agenda-accent); }
    &:hover:not(:disabled) { background: var(--apl-agenda-line); }
    &:disabled { cursor: default; opacity: .5; }
    &.is-today { font-weight: 800; color: var(--apl-agenda-accent); }
