.apl-agenda .apl-agenda-empty { padding: 50px 22px; text-align: center; color: var(--apl-agenda-mute); text-wrap: balance; & b { display: block; color: var(--apl-agenda-ink); font-size: 15px; margin-bottom: 4px; } }

/* rows reveal as they scroll in, driven by the component's own scroller */
@supports (animation-timeline: view()) {
  .apl-agenda .apl-agenda-ev, .apl-agenda .apl-agenda-hop { animation: apl-agenda-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
  .apl-agenda .apl-agenda-chips {
  grid-column: 1 / -1; display: none; gap: 4px; overflow-x: auto; scrollbar-width: none;
  & button { flex: none; display: inline-flex; align-items: center; gap: 6px; border: 0; border-radius: 20px; padding: 5px 11px; background: var(--apl-agenda-line); font-size: 12px; font-weight: 650; color: var(--apl-agenda-mute); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--apl-agenda-ink); color: var(--apl-agenda-bg); }
  & output { font: 700 10.5px ui-monospace, Menlo, monospace; padding: 0 5px; border-radius: 6px; background: var(--apl-agenda-accent); color: var(--apl-agenda-on); }
}
.apl-agenda .apl-agenda-prog { animation: apl-agenda-grow linear both; animation-timeline: --apl-agenda-sc; }
}
@keyframes apl-agenda-reveal { from { opacity: 0; translate: 0 16px; scale: .985; filter: blur(2px); } }
@keyframes apl-agenda-grow { from { scale: 0 1; } to { scale: 1 1; } }
@keyframes apl-agenda-pulse { 0% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--apl-agenda-accent) 60%, transparent); } 70%, 100% { box-shadow: 0 0 0 8px transparent; } }
@keyframes apl-agenda-in { from { opacity: 0; translate: 14px 0; } }

/* ── detail ── */
.apl-agenda .apl-agenda-detail {
  grid-area: detail; min-height: 0; overflow-y: auto; scrollbar-width: none; padding: 22px 20px 18px; border-left: 1px solid var(--apl-agenda-line); background: var(--apl-agenda-panel);
  display: flex; flex-direction: column; gap: 16px;
  & > * { animation: apl-agenda-in .4s var(--apl-agenda-ease) both; animation-delay: calc(var(--i, 0) * 45ms); }
  & .back { display: none; align-self: flex-start; align-items: center; gap: 6px; border: 0; background: none; padding: 4px 0; font-weight: 650; color: var(--apl-agenda-mute); }
  & .kick { display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 750; letter-spacing: .13em; text-transform: uppercase; color: var(--c); }
  & .kick i { width: 8px; height: 8px; border-radius: 3px; background: var(--c); }
