  & button[aria-checked="true"] kbd { color: inherit; border-color: color-mix(in oklch, var(--apl-agenda-bg) 30%, transparent); }
  & button[data-r="yes"][aria-checked="true"] { background: var(--apl-agenda-accent); color: var(--apl-agenda-on); }
}
.apl-agenda .apl-agenda-keys { margin-top: auto; font-size: 11px; color: var(--apl-agenda-faint); line-height: 2.1; text-wrap: pretty; }
.apl-agenda .apl-agenda-toast {
  position: absolute; z-index: 40; left: 50%; bottom: 16px; translate: -50% 150%; opacity: 0; pointer-events: none;
  display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 14px; border-radius: 12px; max-width: calc(100% - 32px);
  background: var(--apl-agenda-ink); color: var(--apl-agenda-bg); font-size: 12.5px; font-weight: 600;
