  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { flex: none; border: 0; border-radius: 8px; padding: 5px 10px; font-weight: 750; background: var(--apl-agenda-accent); color: var(--apl-agenda-on); }
  &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  &:not(.can-undo) button { display: none; }
}

/* ── container-responsive ── */
@container (width < 1100px) {
  .apl-agenda .apl-agenda-app { grid-template-columns: 220px minmax(0, 1fr) 300px; }
}
@container (width < 960px) {
  .apl-agenda .apl-agenda-app { grid-template-columns: minmax(0, 1fr) 300px; grid-template-areas: "list detail"; }
  .apl-agenda .apl-agenda-side { display: none; }
  .apl-agenda .apl-agenda-chips { display: flex; }
}
@container (width < 760px) {
  .apl-agenda .apl-agenda-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "list"; }
  .apl-agenda .apl-agenda-detail { position: absolute; inset: 0; z-index: 20; border: 0; translate: 104% 0; visibility: hidden; transition: translate .45s var(--apl-agenda-spring), visibility 0s .45s; }
  .apl-agenda[data-open="true"] .apl-agenda-detail { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .apl-agenda .apl-agenda-detail .back { display: inline-flex; }
  .apl-agenda .apl-agenda-top { grid-template-columns: minmax(0, 1fr) auto; padding: 14px 14px 12px; }
  .apl-agenda .apl-agenda-search { grid-column: 1 / -1; grid-row: 2; width: auto; }
  .apl-agenda .apl-agenda-search kbd, .apl-agenda .apl-agenda-today kbd, .apl-agenda .apl-agenda-keys { display: none; }
  .apl-agenda .apl-agenda-dh { padding: 10px 14px 8px; }
  .apl-agenda .apl-agenda-rows { padding: 4px 4px 8px; }
  .apl-agenda .apl-agenda-ev { grid-template-columns: 52px 3px minmax(0, 1fr); }
  .apl-agenda .apl-agenda-ev .rs { grid-column: 3; justify-self: start; margin-top: 6px; }
  .apl-agenda .apl-agenda-hop { grid-template-columns: 52px 3px minmax(0, 1fr); }
  .apl-agenda .apl-agenda-gap { margin: 0 14px; padding-left: 64px; }
}

@media (prefers-reduced-motion: reduce) {
  .apl-agenda *, .apl-agenda *::before, .apl-agenda *::after { animation-duration: .01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
  .apl-agenda .apl-agenda-ev, .apl-agenda .apl-agenda-hop { animation: none !important; }
}

