const TODAY = D(2026, 10, 2), FIRST = TODAY, LAST = D(2026, 10, 25);
const tm = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };

const CALS = {
  work: { name: 'Fernweh Labs', c: 'var(--apl-agenda-accent)' },
