let seq = 0;
const ev = (day, s, e, cal, title, loc, o) => Object.assign({ id: 'a' + (++seq), day, s: s ? tm(s) : null, e: e ? tm(e) : null, cal, title, loc, me: 'yes', guests: [], mode: null, travel: 0, org: 'Jonas Vidal', notes: '' }, o || {});
const G = (...a) => a.map(([n, r]) => ({ n, r }));
