  if (RM.matches) { run(); return; }
  const before = new Map(), ghosts = [];
  const fr = feed.getBoundingClientRect();
  $$('.apl-agenda-ev, .apl-agenda-hop, .apl-agenda-dh', feed).forEach(n => before.set(n.dataset.id || n.textContent, { r: n.getBoundingClientRect(), n }));
  run();
  const seen = new Set();
  $$('.apl-agenda-ev, .apl-agenda-hop, .apl-agenda-dh', feed).forEach(n => {
    const k = n.dataset.id || n.textContent, a = before.get(k); seen.add(k);
    if (!a || n.matches('.apl-agenda-dh')) return;
    const b = n.getBoundingClientRect(), dy = a.r.top - b.top;
    if (Math.abs(dy) > 1) n.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 460, easing: SPRING });
  });
  before.forEach((a, k) => {
    if (seen.has(k) || !a.n.matches('.apl-agenda-ev')) return;
    const g = a.n.cloneNode(true);
    Object.assign(g.style, { position: 'absolute', left: (a.r.left - fr.left) + 'px', top: (a.r.top - fr.top) + 'px', width: a.r.width + 'px', margin: 0, pointerEvents: 'none', animation: 'none' });
    feed.append(g);
    g.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(-24px) scale(.97)', filter: 'blur(2px)' }], { duration: 320, easing: 'cubic-bezier(.4,0,1,1)' }).finished.then(() => g.remove(), () => g.remove());
  });
}
function rsvp(id, r) {
  const e = find(id); if (!e || e.me === r || !(e.guests.length && e.org !== 'Jonas Vidal')) return;
  past.push({ id, r: e.me, sel: S.sel });
  const was = e.me;
  const next = visible().filter(x => x.id !== id);
  flip(() => { e.me = r; render(); });
  if (!matches(e)) { const i = visible().length ? next.findIndex(x => sortEv(x, e) > 0) : -1; S.sel = (next[i] || next[next.length - 1] || {}).id || null; markSel(); renderDetail(); }
  const who = e.org.split(' ')[0];
  toast((r === 'yes' ? 'Going to “' : r === 'maybe' ? 'Maybe for “' : 'Declined “') + e.title + '” — ' + who + ' will be told' + (was === 'pend' ? '' : ''), true);
}
function undo() {
  const u = past.pop(); if (!u) { toast('Nothing to undo'); return; }
  const e = find(u.id);
