root.addEventListener('click', e => {
  const t = e.target;
  const row = t.closest('.apl-agenda-ev'), go = t.closest('[data-goto]'), f = t.closest('[data-filter]'), r = t.closest('[data-r]'), a = t.closest('[data-act]');
  if (row && feed.contains(row)) { select(row.dataset.id); if (root.clientWidth < 760) { S.open = true; root.dataset.open = 'true'; } return; }
  if (go) { goto(+go.dataset.goto, true); return; }
  if (f) { S.filter = f.dataset.filter; render(); scroller.scrollTop = 0; return; }
  if (r) { rsvp(S.sel, r.dataset.r); return; }
  if (!a) return;
  if (a.dataset.act === 'today') goto(TODAY, true);
  else if (a.dataset.act === 'undo') undo();
  else if (a.dataset.act === 'close') { S.open = false; root.dataset.open = 'false'; const b = $('.apl-agenda-ev[data-id="' + S.sel + '"]', feed); if (b) b.focus({ preventScroll: true }); }
});
const qi = $('[data-q]');
let qt = 0;
qi.addEventListener('input', () => { clearTimeout(qt); qt = setTimeout(() => { S.q = qi.value.trim(); render(); scroller.scrollTop = 0; }, 90); });
