root.addEventListener('pointerdown', e => { if (!e.target.closest('button, input')) root.focus({ preventScroll: true }); });

/* keep "now" honest */
const tick = setInterval(() => {
  if (!root.isConnected) return clearInterval(tick);
  const n = $('[data-now] span', feed); if (n) n.textContent = hm(nowMin());
}, 30000);

render();

