@property --apl-rooms-ring { syntax: '<number>'; inherits: false; initial-value: 0; }

.apl-rooms {
  /* theme */
  --apl-rooms-bg: oklch(0.205 0.012 170);
  --apl-rooms-ink: oklch(0.95 0.01 160);
