  --apl-rooms-line2: color-mix(in oklch, var(--apl-rooms-ink) 17%, transparent);
  --apl-rooms-mute: color-mix(in oklch, var(--apl-rooms-ink) 58%, var(--apl-rooms-bg));
  --apl-rooms-faint: color-mix(in oklch, var(--apl-rooms-ink) 34%, var(--apl-rooms-bg));
  --apl-rooms-on: oklch(0.22 0.04 166);
  --apl-rooms-mw: 136px; --apl-rooms-hw: 64px;
  --apl-rooms-ease: cubic-bezier(.2, .85, .25, 1);
  --apl-rooms-spring: linear(0, 0.09 4%, 0.35 9%, 0.69 15%, 0.94 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1);

  position: relative; width: 100%; height: var(--apl-rooms-h, 680px);
