  background: var(--apl-rooms-bg); color: var(--apl-rooms-ink); color-scheme: dark; accent-color: var(--apl-rooms-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-rooms-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
