  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; display: inline-block; text-align: center; border: 1px solid var(--apl-rooms-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-rooms-mute); }
