/* ── Kiln House · room booking ───────────────────────────────────────
   One time cursor drives both views: every room's state (free, booked
   soon, in use) and its countdown ring are derived from the same booking
   list at minute S.t, whether you scrub, drag the cursor or press arrows. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
