const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const p2 = n => String(n).padStart(2, '0');
const hm = m => p2(Math.floor(m / 60)) + ':' + p2(m % 60);
const dur = m => { const h = Math.floor(m / 60), r = m % 60; return ((h ? h + 'h' : '') + (h && r ? ' ' : '') + (r ? r + 'm' : '')) || '0m'; };
const DAY = 864e5;
const D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const TODAY = D(2026, 10, 2), OPEN = 480, CLOSE = 1200;
const tm = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };
const ME = 'Mikkel Sand';

const EQ = {
  display: ['Display', '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4.5" width="18" height="12" rx="2"/><path d="M9 20h6M12 16.5V20"/></svg>'],
  video: ['Video bar', '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="7" width="12.5" height="10" rx="2.5"/><path d="m15.5 11 5-3v8l-5-3"/></svg>'],
  board: ['Whiteboard', '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3.5" y="4.5" width="17" height="12" rx="1.5"/><path d="M8 20l2-3.5M16 20l-2-3.5M7.5 9.5c2-1.5 3.5 1.5 5.5 0s3 0 3.5.5"/></svg>'],
  access: ['Step-free', '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="4.5" r="1.8"/><path d="M12 7.5v6h4.5l2 4.5M12 10h4M8.5 11.5a5 5 0 1 0 6.8 6.1"/></svg>'],
};
const ROOMS = [
  { id: 'havn', name: 'Havn', seats: 20, eq: ['display', 'video', 'access'], r: [20, 20, 200, 100] },
  { id: 'fjeld', name: 'Fjeld', seats: 12, eq: ['display', 'video', 'board', 'access'], r: [220, 20, 150, 100] },
  { id: 'bolge', name: 'B\u00f8lge', seats: 8, eq: ['display', 'video'], r: [370, 20, 130, 100] },
  { id: 'lys', name: 'Lys', seats: 6, eq: ['display', 'board'], r: [500, 20, 110, 100] },
  { id: 'ask', name: 'Ask', seats: 4, eq: ['display'], r: [720, 20, 80, 100] },
  { id: 'mos', name: 'Mos', seats: 4, eq: ['board', 'access'], r: [800, 20, 80, 100] },
  { id: 'ild', name: 'Ild', seats: 2, eq: ['video'], r: [510, 170, 60, 140] },
  { id: 'so', name: 'S\u00f8', seats: 2, eq: [], r: [570, 170, 60, 140] },
];
const R = Object.fromEntries(ROOMS.map(r => [r.id, r]));
const PEOPLE = ['Signe Dahl', 'Rasmus Kjær', 'Amira Haddad', 'Jonas Berg', 'Lea Thorsen', 'Oskar Lind'];
const HAND = {
  havn: [['10:00', '12:00', 'Customer workshop: Nordlys Bank', 'Rasmus Kjær'], ['16:00', '17:00', 'Friday all-hands', 'Signe Dahl']],
  fjeld: [['09:30', '10:30', 'Product review', 'Amira Haddad'], ['13:00', '14:30', 'Q4 planning', 'Signe Dahl'], ['15:00', '16:00', 'Interview panel', 'Lea Thorsen']],
  bolge: [['10:00', '11:00', 'Design crit', 'Jonas Berg'], ['11:30', '12:00', 'Vendor call', 'Oskar Lind'], ['14:00', '15:30', 'Data guild', 'Amira Haddad']],
  lys: [['09:00', '10:00', '1:1s', 'Signe Dahl'], ['12:00', '13:00', 'Lunch & learn: accessibility', 'Lea Thorsen'], ['15:30', '17:00', 'Roadmap jam', 'Jonas Berg']],
  ask: [['10:30', '11:30', 'Pairing: billing export', 'Oskar Lind'], ['13:30', '14:00', 'Recruiter sync', 'Lea Thorsen'], ['16:00', '17:30', 'Sprint retro', 'Rasmus Kjær']],
  mos: [['09:00', '09:45', 'Standup: Payments', 'Rasmus Kjær'], ['11:00', '12:30', 'Workshop prep', ME], ['14:30', '15:30', 'Mentoring', 'Amira Haddad']],
  ild: [['09:30', '10:00', 'Call: Fyrtårn Freight', 'Oskar Lind'], ['13:00', '13:30', 'Call: landlord', ME], ['15:00', '16:00', 'Focus', 'Jonas Berg']],
  so: [['11:00', '11:30', 'Call', 'Lea Thorsen'], ['14:00', '14:30', 'Call', 'Amira Haddad']],
};
let seq = 0;
const BK = new Map();     /* day -> [{id, room, s, e, title, who}] */
function seeded(n) { let h = n * 2654435761 >>> 0; return () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) ^ Math.imul(h ^ (h >>> 13), 3266489909)) >>> 0) / 4294967296; }
function dayBookings(day) {
  if (BK.has(day)) return BK.get(day);
  const out = [];
  if (day === TODAY) Object.entries(HAND).forEach(([room, list]) => list.forEach(([s, e, t, w]) => out.push({ id: 'b' + (++seq), room, s: tm(s), e: tm(e), title: t, who: w })));
  else if (dow(day) % 6) {
    const r = seeded(day), titles = ['Design crit', 'Planning', 'Interview', 'Customer call', 'Workshop', 'Sync', 'Retro', '1:1'];
    ROOMS.forEach(room => {
      let t = 540 + Math.floor(r() * 4) * 30;
      while (t < 1050) {
        const d = room.seats <= 2 ? 30 : [30, 60, 60, 90][Math.floor(r() * 4)];
        if (r() < .55) out.push({ id: 'b' + (++seq), room: room.id, s: t, e: t + d, title: titles[Math.floor(r() * titles.length)], who: PEOPLE[Math.floor(r() * PEOPLE.length)] });
        t += d + 30 * (1 + Math.floor(r() * 3));
      }
    });
  }
  BK.set(day, out);
  return out;
}

/* ── state ── */
const nowMin = () => { const t = new Date(); return t.getHours() * 60 + t.getMinutes(); };
const snap15 = m => Math.round(m / 15) * 15;
const S = { day: TODAY, t: clamp(snap15(nowMin()), OPEN, CLOSE - 15), sel: 'fjeld', seats: 0, eq: new Set(), tab: 'plan' };
if (nowMin() < OPEN || nowMin() > CLOSE - 15) S.t = 870;
const past = [];
const svg = $('[data-svg]'), pins = $('[data-pins]'), rowsEl = $('[data-rows]'), side = $('[data-side]'), cursor = $('[data-cursor]'), range = $('[data-range]'), pop = $('[data-pop]'), toastEl = $('[data-toast]'), tscroll = $('[data-tscroll]');
const hw = () => parseFloat(getComputedStyle($('[data-sheet]')).getPropertyValue('--apl-rooms-hw')) || 64;
const books = (room, day) => dayBookings(day == null ? S.day : day).filter(b => b.room === room).sort((a, b) => a.s - b.s);
const fits = r => r.seats >= S.seats && [...S.eq].every(k => r.eq.includes(k));
function stateAt(room, t) {
  const bs = books(room.id), cur = bs.find(b => b.s <= t && b.e > t);
  if (cur) return { k: 'busy', cur, ring: (cur.e - t) / (cur.e - cur.s), line: '\u2192 ' + hm(cur.e) };
  const nx = bs.find(b => b.s > t);
  if (nx && nx.s - t <= 30) return { k: 'soon', next: nx, ring: (nx.s - t) / 30, line: 'at ' + hm(nx.s) };
  const free = (nx ? nx.s : CLOSE) - t;
  return { k: 'free', next: nx, free, ring: Math.min(1, free / 180), line: nx ? dur(free) + ' free' : 'all day' };
}

/* ── static drawing ── */
/* the floor is drawn landscape; in a narrow container it is redrawn rotated
   (x↔y) so rooms keep a readable size and the plan scrolls instead of shrinking */
let portrait = null;
function drawPlan(p) {
  if (p === portrait) return;
  portrait = p;
  const T = (x, y, w, h) => p ? [y, x, h, w] : [x, y, w, h];
  const VW = p ? 330 : 900, VH = p ? 900 : 330;
  const rect = (x, y, w, h, cls, rx) => { [x, y, w, h] = T(x, y, w, h); return '<rect class="' + cls + '" x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="' + (rx || 6) + '"/>'; };
  const text = (x, y, t) => { const [a, b] = T(x, y, 0, 0); return '<text class="lab" x="' + a + '" y="' + b + '" text-anchor="middle"' + (p ? ' transform="rotate(90 ' + a + ' ' + b + ')"' : '') + '>' + t + '</text>'; };
  svg.setAttribute('viewBox', '0 0 ' + VW + ' ' + VH);
  $('[data-box]').dataset.o = p ? 'p' : 'l';
  let h = rect(10, 10, 880, 310, 'wall', 14);
  h += rect(610, 20, 110, 100, 'zone') + text(665, 74, 'Kitchen');
  h += rect(20, 170, 390, 140, 'zone') + text(215, 302, 'Open studio');
  for (let i = 0; i < 5; i++) for (let j = 0; j < 3; j++) h += rect(42 + i * 74, 186 + j * 34, 54, 18, 'desk', 3);
  h += rect(420, 170, 80, 140, 'zone') + text(460, 244, 'Stairs');
  h += rect(640, 170, 240, 140, 'zone') + text(760, 244, 'Reception');
  h += text(450, 149, 'Corridor');
  ROOMS.forEach(r => {
    const [x, y, w, hh] = r.r, [a, b, c, d] = T(x + 3, y + 3, w - 6, hh - 6);
    h += '<rect class="room" data-room="' + r.id + '" x="' + a + '" y="' + b + '" width="' + c + '" height="' + d + '" rx="8"/>';
  });
  svg.innerHTML = h;
  pins.innerHTML = ROOMS.map(r => {
    const [x, y, w, hh] = r.r, [cx, cy] = T(x + w / 2, y + hh / 2, 0, 0), vw = p ? hh : w;
    return '<div class="apl-rooms-pin' + (vw < 80 ? ' tiny' : '') + '" data-pin="' + r.id + '" style="--x:' + (cx / VW * 100) + ';--y:' + (cy / VH * 100) + '"><span class="rg"></span><b>' + r.name + '</b><small></small></div>';
  }).join('');
}
(function chrome() {
  $('[data-ruler]').innerHTML = '<span class="cn"></span>' + Array.from({ length: 12 }, (_, i) => '<span>' + p2(8 + i) + ':00</span>').join('');
  $('[data-cap]').innerHTML = [[0, 'Any'], [4, '4+'], [8, '8+'], [12, '12+']].map(([n, l]) => '<button type="button" role="radio" data-seats="' + n + '" aria-checked="' + (S.seats === n) + '">' + l + '</button>').join('');
  $('[data-eq]').innerHTML = Object.entries(EQ).map(([k, [l, ic]]) => '<button type="button" data-eqk="' + k + '" aria-pressed="false" title="' + l + '">' + ic + '<span>' + l + '</span></button>').join('');
})();
drawPlan(root.clientWidth > 0 && root.clientWidth < 600);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const p = root.clientWidth < 600;
  if (p !== portrait) { drawPlan(p); renderPlan(); }
});
ro.observe(root);

/* ── live render ── */
function renderPlan() {
  ROOMS.forEach(r => {
    const st = stateAt(r, S.t), on = fits(r);
