    el.setAttribute('class', 'room ' + (on ? st.k : 'off') + (S.sel === r.id ? ' sel' : ''));
    const pin = $('[data-pin="' + r.id + '"]', pins);
    pin.className = 'apl-rooms-pin ' + (on ? st.k : 'off') + ((portrait ? r.r[3] : r.r[2]) < 80 ? ' tiny' : '') + (S.sel === r.id ? ' sel' : '');
    $('.rg', pin).style.setProperty('--apl-rooms-ring', st.ring.toFixed(3));
