    $('small', pin).textContent = st.line;
  });
}
function renderRows() {
  rowsEl.innerHTML = ROOMS.map(r => {
    const on = fits(r);
    return '<div class="apl-rooms-row' + (on ? '' : ' off') + (S.sel === r.id ? ' sel' : '') + '" data-row="' + r.id + '"><button type="button" class="apl-rooms-rn" data-pick="' + r.id + '"><i></i><b>' + r.name + '</b><small>' + r.seats + ' seats</small></button><div class="apl-rooms-trk" data-trk="' + r.id + '">' +
      books(r.id).map(b => '<span class="apl-rooms-bk' + (b.who === ME ? ' mine' : '') + (b.id === S.fresh ? ' is-new' : '') + '" data-bk="' + b.id + '" style="--s:' + b.s + ';--d:' + (b.e - b.s) + '" title="' + esc(b.title) + ' · ' + hm(b.s) + '–' + hm(b.e) + ' · ' + esc(b.who) + '"><span>' + esc(b.title) + '</span></span>').join('') + '</div></div>';
  }).join('');
  S.fresh = null;
  const nl = $('.apl-rooms-nowl', $('[data-sheet]'));
  const nm = nowMin(), showNow = S.day === TODAY && nm >= OPEN && nm <= CLOSE;
  if (showNow) { const n = nl || doc.createElement('i'); n.className = 'apl-rooms-nowl'; n.style.setProperty('--t', nm); if (!nl) $('[data-sheet]').append(n); } else if (nl) nl.remove();
}
function renderCursor() {
  cursor.style.setProperty('--t', S.t);
  $('i', cursor).dataset.t = hm(S.t);
  range.value = S.t;
  $('[data-at]').textContent = hm(S.t);
  ROOMS.forEach(r => { const row = $('[data-row="' + r.id + '"]', rowsEl); if (row) row.style.setProperty('--st', 'var(--apl-rooms-' + ({ free: 'accent', soon: 'soon', busy: 'busy' })[stateAt(r, S.t).k] + ')'); });
}
function renderSide() {
  const r = R[S.sel], st = stateAt(r, S.t), bs = books(r.id), col = { free: 'var(--apl-rooms-accent)', soon: 'var(--apl-rooms-soon)', busy: 'var(--apl-rooms-busy)' }[st.k];
  const can = d => { const s = S.t, e = s + d; return e <= CLOSE && !bs.some(b => b.s < e && b.e > s); };
  const used = bs.reduce((t, b) => t + b.e - b.s, 0);
  let i = 0;
