@property --apl-year-t { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --apl-year-b { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --apl-year-p { syntax: '<number>'; inherits: true; initial-value: 0; }

.apl-year {
  /* theme */
  --apl-year-bg: oklch(0.985 0.006 95);
  --apl-year-ink: oklch(0.24 0.012 80);
  --apl-year-accent: oklch(0.45 0.13 262);
  --apl-year-heat: oklch(0.7 0.15 55);
  --apl-year-surface: oklch(0.997 0.003 95);
