  --apl-year-line2: color-mix(in oklch, var(--apl-year-ink) 17%, transparent);
  --apl-year-mute: color-mix(in oklch, var(--apl-year-ink) 56%, var(--apl-year-bg));
  --apl-year-faint: color-mix(in oklch, var(--apl-year-ink) 32%, var(--apl-year-bg));
  --apl-year-h1: color-mix(in oklab, var(--apl-year-heat) 16%, var(--apl-year-surface));
  --apl-year-h2: color-mix(in oklab, var(--apl-year-heat) 34%, var(--apl-year-surface));
  --apl-year-h3: color-mix(in oklab, var(--apl-year-heat) 58%, var(--apl-year-surface));
  --apl-year-h4: var(--apl-year-heat);
  --apl-year-ease: cubic-bezier(.2, .85, .25, 1);
  --apl-year-spring: linear(0, 0.09 4%, 0.34 9%, 0.68 15%, 0.93 22%, 1.05 28%, 1.07 33%, 1.04 40%, 1.01 50%, 0.997 62%, 1);

  position: relative; width: 100%; height: var(--apl-year-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apl-year-bg); color: var(--apl-year-ink); color-scheme: light; accent-color: var(--apl-year-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px;
  box-shadow: 0 0 0 1px var(--apl-year-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--apl-year-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & h2, & h3, & p, & ol, & ul, & dl { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 5px; min-width: 17px; display: inline-block; text-align: center; border: 1px solid var(--apl-year-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--apl-year-mute); background: var(--apl-year-surface); }
}
.apl-year .apl-year-app {
  height: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 296px; grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "head head" "cal side";
