}
.apl-year .apl-year-d {
  position: relative; aspect-ratio: 1; min-width: 0; display: grid; place-items: center; padding: 0; border: 0; border-radius: 5px; touch-action: manipulation;
  font-size: 10px; font-weight: 550; font-variant-numeric: tabular-nums; color: var(--apl-year-ink); background: var(--apl-year-surface);
  box-shadow: inset 0 0 0 1px var(--apl-year-line); cursor: pointer;
