/* ── Tamarind Health · leave planner ────────────────────────────────
   365 day cells in twelve small grids. Each cell carries the team-absence
   count as data-h (the heatmap), and a selection is costed in working days:
   weekends and England & Wales bank holidays never count against you. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
$$('[data-mod]').forEach(k => { k.textContent = MAC ? '⌘' : 'Ctrl'; });
const DAY = 864e5;
const D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MS = MONTHS.map(m => m.slice(0, 3));
const Y0 = D(2026, 1, 1), Y1 = D(2026, 12, 31), TODAY = D(2026, 10, 2);
const lab = d => { const [, m, n] = ymd(d); return WD[dow(d)] + ' ' + n + ' ' + MS[m]; };
const span = (a, b) => a === b ? lab(a) : lab(a) + ' – ' + lab(b);

const HOL = {
  [D(2026, 1, 1)]: 'New Year’s Day', [D(2026, 4, 3)]: 'Good Friday', [D(2026, 4, 6)]: 'Easter Monday', [D(2026, 5, 4)]: 'Early May bank holiday',
  [D(2026, 5, 25)]: 'Spring bank holiday', [D(2026, 8, 31)]: 'Summer bank holiday', [D(2026, 12, 25)]: 'Christmas Day', [D(2026, 12, 28)]: 'Boxing Day (substitute)',
};
const working = d => dow(d) % 6 !== 0 && !HOL[d];
const wdays = (a, b) => { let n = 0; for (let d = a; d <= b; d++) if (working(d)) n++; return n; };
const ALLOW = 25, CARRY = 3, MANAGER = 'Nadia Petrova';
const TYPES = ['Vacation', 'Personal', 'Learning'];
let rid = 0;
const rq = (s, e, type, note, st) => ({ id: 'r' + (++rid), s, e, type, note, st });
let REQ = [
  rq(D(2026, 2, 16), D(2026, 2, 20), 'Vacation', 'Skiing, Jura', 'ok'),
  rq(D(2026, 4, 7), D(2026, 4, 10), 'Vacation', 'Easter in Porto', 'ok'),
  rq(D(2026, 5, 26), D(2026, 5, 27), 'Personal', 'Moving flat', 'ok'),
  rq(D(2026, 10, 26), D(2026, 10, 30), 'Vacation', 'Half-term, Lisbon', 'ok'),
  rq(D(2026, 11, 13), D(2026, 11, 13), 'Learning', 'Type design workshop', 'ok'),
  rq(D(2026, 12, 21), D(2026, 12, 24), 'Vacation', 'Christmas in Accra', 'pend'),
];

/* team absences: seeded per person so the heatmap is stable, with the usual UK peaks */
const TEAM = ['Ama Owusu', 'Ben Hartley', 'Chloe Fenwick', 'Dev Malhotra', 'Elif Kaya', 'Finn Doyle', 'Grace Lam', 'Hugo Barros', 'Isla Murray'];
const OFF = new Map();   /* day -> [names] */
(function team() {
  TEAM.forEach((name, i) => {
    let h = (i + 7) * 2654435761 >>> 0;
    const r = () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) ^ Math.imul(h ^ (h >>> 13), 3266489909)) >>> 0) / 4294967296;
    const starts = [D(2026, 7, 27) + Math.floor(r() * 28), D(2026, 2, 2) + Math.floor(r() * 120), D(2026, 5, 18) + Math.floor(r() * 50), D(2026, 9, 7) + Math.floor(r() * 60)];
    if (r() < .65) starts.push(D(2026, 12, 21) + Math.floor(r() * 4));
    if (r() < .4) starts.push(D(2026, 4, 1) + Math.floor(r() * 6));
    if (r() < .45) starts.push(D(2026, 10, 26));
    starts.forEach(s => { const len = 3 + Math.floor(r() * 8); for (let d = s; d < s + len && d <= Y1; d++) if (working(d)) { if (!OFF.has(d)) OFF.set(d, []); if (!OFF.get(d).includes(name)) OFF.get(d).push(name); } });
  });
})();
const heat = d => { const n = (OFF.get(d) || []).length; return n >= 4 ? 4 : n; };

/* ── balance: every figure is derived from REQ ── */
function balance() {
  let taken = 0, booked = 0, pend = 0;
  REQ.forEach(r => { const n = wdays(r.s, r.e); if (r.st === 'pend') pend += n; else if (r.e < TODAY) taken += n; else booked += n; });
  return { taken, booked, pend, left: ALLOW + CARRY - taken - booked - pend };
}
const reqOn = d => REQ.find(r => d >= r.s && d <= r.e);

/* ── state ── */
const S = { focus: TODAY, anchor: null, sel: null, type: 'Vacation', heat: 'team', tab: 'year', hi: null };
const past = [];
const monthsEl = $('[data-months]'), card = $('[data-card]'), tip = $('[data-tip]'), toastEl = $('[data-toast]');
const cells = new Map();

function build() {
  let h = '';
  for (let m = 0; m < 12; m++) {
    const first = D(2026, m + 1, 1), last = D(2026, m + 2, 1) - 1, lead = (dow(first) + 6) % 7;
    h += '<section class="apl-year-month' + (last < TODAY ? ' is-past' : '') + '" style="--i:' + m + '" data-m="' + m + '"><header><b>' + MONTHS[m] + '</b><small data-mc="' + m + '"></small></header><div class="wk" role="row">' +
      ['M', 'T', 'W', 'T', 'F', 'S', 'S'].map(x => '<span class="dw" aria-hidden="true">' + x + '</span>').join('') +
      Array.from({ length: lead }, () => '<span class="apl-year-d pad" aria-hidden="true"></span>').join('');
    for (let d = first; d <= last; d++) h += '<button type="button" class="apl-year-d" role="gridcell" data-d="' + d + '" tabindex="-1">' + ymd(d)[2] + '</button>';
    h += '</div></section>';
  }
  monthsEl.innerHTML = h;
  $$('[data-d]', monthsEl).forEach(b => cells.set(+b.dataset.d, b));
}
function paint() {
  const [a, b] = S.sel || [-1, -2];
  cells.forEach((el, d) => {
    const r = reqOn(d), we = dow(d) % 6 === 0;
    const cls = ['apl-year-d', we && 'we', HOL[d] && 'hol', d < TODAY && 'past', d === TODAY && 'today',
      r && working(d) && 'my', r && working(d) && (r.st === 'pend' ? 'pend' : r.e < TODAY ? 'taken' : ''),
      d >= a && d <= b && 'in', (d === a || d === b) && S.sel && 'end'].filter(Boolean).join(' ');
    if (el.className !== cls) el.className = cls;
    const hv = we || HOL[d] ? '' : String(heat(d));
    if (hv && hv !== '0') el.dataset.h = hv; else el.removeAttribute('data-h');
    el.tabIndex = d === S.focus ? 0 : -1;
    el.setAttribute('aria-selected', String(d >= a && d <= b));
    const who = OFF.get(d) || [];
    el.setAttribute('aria-label', lab(d) + (HOL[d] ? ', ' + HOL[d] : we ? ', weekend' : '') + (r ? ', your ' + r.type.toLowerCase() + (r.st === 'pend' ? ' (pending)' : '') : '') + (who.length ? ', ' + who.length + ' teammate' + (who.length === 1 ? '' : 's') + ' off' : ''));
  });
  for (let m = 0; m < 12; m++) {
    const first = D(2026, m + 1, 1), last = D(2026, m + 2, 1) - 1;
    let n = 0; REQ.forEach(r => { n += wdays(Math.max(r.s, first), Math.min(r.e, last)); });
    $('[data-mc="' + m + '"]').textContent = n ? n + 'd off' : '';
  }
}
let lastLeft = null;
function renderSide() {
  const b = balance(), tot = ALLOW + CARRY;
  const ring = $('[data-ring]');
  ring.style.setProperty('--apl-year-t', (b.taken / tot).toFixed(4));
  ring.style.setProperty('--apl-year-b', (b.booked / tot).toFixed(4));
  ring.style.setProperty('--apl-year-p', (b.pend / tot).toFixed(4));
  ring.setAttribute('aria-label', b.left + ' of ' + tot + ' days left');
